37	    auto uniqueExecutor = CREATE_EXECUTOR();
38	
39	    // Handle non-contiguous x input via CreateView (dual shape descriptor, zero-copy).
40	    // For contiguous tensors, view shape == storage shape, so this is a no-op.
41	    aclTensor *xFinal =
42	        uniqueExecutor->CreateView(x, x->GetViewShape(), x->GetStorageShape(), x->GetViewStrides(), x->GetViewOffset());
43	    CHECK_COND(xFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "CreateView for x failed.");
44	
45	    aclTensor *convStates = uniqueExecutor->CreateView(convStatesRef,
46	        convStatesRef->GetViewShape(),
47	        convStatesRef->GetStorageShape(),
48	        convStatesRef->GetViewStrides(),
49	        convStatesRef->GetViewOffset());
50	    CHECK_COND(convStates != nullptr, ACLNN_ERR_INNER_NULLPTR, "CreateView for convStates failed.");
51	
52	    weight = l0op::Contiguous(weight, uniqueExecutor.get());
53	    CHECK_COND(weight != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous weight failed.");
54	
55	    if (cacheIndices != nullptr) {
56	        cacheIndices = l0op::Contiguous(cacheIndices, uniqueExecutor.get());
57	        CHECK_COND(cacheIndices != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous cacheIndices failed.");
58	    }
59	
60	    if (queryStartLocOptional != nullptr) {
61	        queryStartLocOptional = l0op::Contiguous(queryStartLocOptional, uniqueExecutor.get());
62	        CHECK_COND(queryStartLocOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous queryStartLoc failed.");
63	    }
64	    if (initialStateModeOptional != nullptr) {
65	        initialStateModeOptional = l0op::Contiguous(initialStateModeOptional, uniqueExecutor.get());
66	        CHECK_COND(initialStateModeOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous initialStateMode failed.");
67	    }
68	    if (biasOptional != nullptr) {
69	        biasOptional = l0op::Contiguous(biasOptional, uniqueExecutor.get());
70	        CHECK_COND(biasOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous bias failed.");
71	    }
72	    if (numAcceptedTokensOptional != nullptr) {
73	        numAcceptedTokensOptional = l0op::Contiguous(numAcceptedTokensOptional, uniqueExecutor.get());
74	        CHECK_COND(
75	            numAcceptedTokensOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous numAcceptedTokens failed.");
76	    }
77	
78	    if (numComputedTokens != nullptr) {
79	        numComputedTokens = l0op::Contiguous(numComputedTokens, uniqueExecutor.get());
80	        CHECK_COND(numComputedTokens != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous numComputedTokens failed.");
81	    }
82	
83	    if (blockIdxFirstScheduledToken != nullptr) {
84	        blockIdxFirstScheduledToken = l0op::Contiguous(blockIdxFirstScheduledToken, uniqueExecutor.get());
85	        CHECK_COND(blockIdxFirstScheduledToken != nullptr,
86	            ACLNN_ERR_INNER_NULLPTR,
87	            "Contiguous blockIdxFirstScheduledToken failed.");
88	    }
89	
90	    if (blockIdxLastScheduledToken != nullptr) {
91	        blockIdxLastScheduledToken = l0op::Contiguous(blockIdxLastScheduledToken, uniqueExecutor.get());
92	        CHECK_COND(blockIdxLastScheduledToken != nullptr,
93	            ACLNN_ERR_INNER_NULLPTR,
94	            "Contiguous blockIdxLastScheduledToken failed.");
95	    }
96	
97	    if (initialStateIdx != nullptr) {
98	        initialStateIdx = l0op::Contiguous(initialStateIdx, uniqueExecutor.get());
99	        CHECK_COND(initialStateIdx != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous initialStateIdx failed.");
100	    }
101	
102	    // convStates is an in-place update: the same tensor serves as both input and
103	    // output. yOut is always contiguous. Both are passed directly to l0op.
104	    // L0接口设计返回值为bool，因为不对返回值的aclTensor再做shape的check
105	    bool ok = l0op::AiInfraFusedCausalConv1d(xFinal,
106	        weight,
107	        convStates,
108	        queryStartLocOptional,
109	        cacheIndices,
110	        initialStateModeOptional,
111	        biasOptional,
112	        numAcceptedTokensOptional,
113	        numComputedTokens,
