119	        runMode,
120	        maxQueryLen,
121	        residualConnection,
122	        blockSize,
123	        convMode,
124	        inplace,
125	        yOut,
126	        uniqueExecutor.get());
127	    CHECK_RET(ok, ACLNN_ERR_INNER_NULLPTR);
128	
129	    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
130	    uniqueExecutor.ReleaseTo(executor);
131	    return ACLNN_SUCCESS;
