#include "aclnn_kernels/common/op_error_check.h"
#include "opdev/common_types.h"
#include "opdev/op_dfx.h"
#include "opdev/op_executor.h"
#include "opdev/make_op_executor.h"
#include "aclnn_kernels/contiguous.h"
#include "opdev/op_log.h"
#include "ai_infra_fused_causal_conv1d.h"
#include "aclnn_ai_infra_fused_causal_conv1d.h"

using namespace op;

#ifdef __cplusplus
extern "C" {
#endif

namespace {

aclnnStatus AiInfraFusedCausalConv1dCommonProcess(aclTensor *x, const aclTensor *weight, aclTensor *convStatesRef,
    const aclTensor *queryStartLocOptional, const aclTensor *cacheIndices, const aclTensor *initialStateModeOptional,
    const aclTensor *biasOptional, const aclTensor *numAcceptedTokensOptional, const aclTensor *numComputedTokens,
    const aclTensor *blockIdxFirstScheduledToken, const aclTensor *blockIdxLastScheduledToken,
    const aclTensor *initialStateIdx, int64_t activationMode, int64_t padSlotId, int64_t runMode, int64_t maxQueryLen,
    int64_t residualConnection, int64_t blockSize, int64_t convMode, bool inplace, const aclTensor *yOut,
    uint64_t *workspaceSize, aclOpExecutor **executor)
{
    auto uniqueExecutor = CREATE_EXECUTOR();

    // Handle non-contiguous x input via CreateView (dual shape descriptor, zero-copy).
    // For contiguous tensors, view shape == storage shape, so this is a no-op.
    aclTensor *xFinal =
        uniqueExecutor->CreateView(x, x->GetViewShape(), x->GetStorageShape(), x->GetViewStrides(), x->GetViewOffset());
    CHECK_COND(xFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "CreateView for x failed.");

    aclTensor *convStates = uniqueExecutor->CreateView(convStatesRef,
        convStatesRef->GetViewShape(),
        convStatesRef->GetStorageShape(),
        convStatesRef->GetViewStrides(),
        convStatesRef->GetViewOffset());
    CHECK_COND(convStates != nullptr, ACLNN_ERR_INNER_NULLPTR, "CreateView for convStates failed.");

    weight = l0op::Contiguous(weight, uniqueExecutor.get());
    CHECK_COND(weight != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous weight failed.");

    if (cacheIndices != nullptr) {
        cacheIndices = l0op::Contiguous(cacheIndices, uniqueExecutor.get());
        CHECK_COND(cacheIndices != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous cacheIndices failed.");
    }

    if (queryStartLocOptional != nullptr) {
        queryStartLocOptional = l0op::Contiguous(queryStartLocOptional, uniqueExecutor.get());
        CHECK_COND(queryStartLocOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous queryStartLoc failed.");
    }
    if (initialStateModeOptional != nullptr) {
        initialStateModeOptional = l0op::Contiguous(initialStateModeOptional, uniqueExecutor.get());
        CHECK_COND(initialStateModeOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous initialStateMode failed.");
    }
    if (biasOptional != nullptr) {
        biasOptional = l0op::Contiguous(biasOptional, uniqueExecutor.get());
        CHECK_COND(biasOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous bias failed.");
    }
    if (numAcceptedTokensOptional != nullptr) {
        numAcceptedTokensOptional = l0op::Contiguous(numAcceptedTokensOptional, uniqueExecutor.get());
        CHECK_COND(
            numAcceptedTokensOptional != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous numAcceptedTokens failed.");
    }

    if (numComputedTokens != nullptr) {
        numComputedTokens = l0op::Contiguous(numComputedTokens, uniqueExecutor.get());
        CHECK_COND(numComputedTokens != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous numComputedTokens failed.");
    }

    if (blockIdxFirstScheduledToken != nullptr) {
        blockIdxFirstScheduledToken = l0op::Contiguous(blockIdxFirstScheduledToken, uniqueExecutor.get());
        CHECK_COND(blockIdxFirstScheduledToken != nullptr,
            ACLNN_ERR_INNER_NULLPTR,
            "Contiguous blockIdxFirstScheduledToken failed.");
    }

    if (blockIdxLastScheduledToken != nullptr) {
        blockIdxLastScheduledToken = l0op::Contiguous(blockIdxLastScheduledToken, uniqueExecutor.get());
        CHECK_COND(blockIdxLastScheduledToken != nullptr,
            ACLNN_ERR_INNER_NULLPTR,
            "Contiguous blockIdxLastScheduledToken failed.");
    }

    if (initialStateIdx != nullptr) {
        initialStateIdx = l0op::Contiguous(initialStateIdx, uniqueExecutor.get());
        CHECK_COND(initialStateIdx != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous initialStateIdx failed.");
    }

    // convStates is an in-place update: the same tensor serves as both input and
    // output. yOut is always contiguous. Both are passed directly to l0op.
    // L0接口设计返回值为bool，因为不对返回值的aclTensor再做shape的check
    bool ok = l0op::AiInfraFusedCausalConv1d(xFinal,
        weight,
        convStates,
        queryStartLocOptional,
        cacheIndices,
        initialStateModeOptional,
        biasOptional,
        numAcceptedTokensOptional,
        numComputedTokens,
        blockIdxFirstScheduledToken,
        blockIdxLastScheduledToken,
        initialStateIdx,
        activationMode,
        padSlotId,
        runMode,
        maxQueryLen,
        residualConnection,
        blockSize,
        convMode,
        inplace,
        yOut,
        uniqueExecutor.get());
    CHECK_RET(ok, ACLNN_ERR_INNER_NULLPTR);

    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
    uniqueExecutor.ReleaseTo(executor);
    return ACLNN_SUCCESS;
}

}  // namespace

aclnnStatus aclnnAiInfraFusedCausalConv1dGetWorkspaceSize(aclTensor *x, const aclTensor *weight,
    aclTensor *convStatesRef, const aclTensor *queryStartLocOptional, const aclTensor *cacheIndices,
    const aclTensor *initialStateModeOptional, const aclTensor *biasOptional,
    const aclTensor *numAcceptedTokensOptional, const aclTensor *numComputedTokens,
    const aclTensor *blockIdxFirstScheduledToken, const aclTensor *blockIdxLastScheduledToken,
    const aclTensor *initialStateIdx, int64_t activationMode, int64_t padSlotId, int64_t runMode, int64_t maxQueryLen,
    int64_t residualConnection, int64_t blockSize, int64_t convMode, bool inplace, const aclTensor *yOut,
    uint64_t *workspaceSize, aclOpExecutor **executor)
{
    L2_DFX_PHASE_1(aclnnAiInfraFusedCausalConv1d,
        DFX_IN(x,
            weight,
            convStatesRef,
            queryStartLocOptional,
            cacheIndices,
            initialStateModeOptional,
            biasOptional,
            numAcceptedTokensOptional,
            numComputedTokens,
            blockIdxFirstScheduledToken,
            blockIdxLastScheduledToken,
            initialStateIdx),
        DFX_OUT(convStatesRef, yOut));
    return AiInfraFusedCausalConv1dCommonProcess(x,
        weight,
        convStatesRef,
        queryStartLocOptional,
        cacheIndices,
        initialStateModeOptional,
        biasOptional,
        numAcceptedTokensOptional,
        numComputedTokens,
        blockIdxFirstScheduledToken,
        blockIdxLastScheduledToken,
        initialStateIdx,
        activationMode,
        padSlotId,
        runMode,
        maxQueryLen,
        residualConnection,
        blockSize,
        convMode,
        inplace,
        yOut,
        workspaceSize,
        executor);
}

aclnnStatus aclnnAiInfraFusedCausalConv1d(
    void *workspace, uint64_t workspaceSize, aclOpExecutor *executor, aclrtStream stream)
{
    L2_DFX_PHASE_2(aclnnAiInfraFusedCausalConv1d);
    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
}

#ifdef __cplusplus
}
#endif

