/*!
 * \file ai_infra_fused_causal_conv1d_common.h
 * \brief
 */
#ifndef _AI_INFRA_FUSED_CAUSAL_CONV1D_COMMON_H_
#define _AI_INFRA_FUSED_CAUSAL_CONV1D_COMMON_H_
#include "kernel_operator.h"
#include "kernel_tiling/kernel_tiling.h"
#include "kernel_utils.h"

namespace AiInfraFusedCausalConv1d {
using namespace AscendC;

constexpr int64_t DOUBLE_BUFFER_NUM = 2;
constexpr int64_t NUM_ZERO = 0;
constexpr int64_t NUM_ONE = 1;
constexpr int64_t NUM_TWO = 2;
constexpr int64_t NUM_THREE = 3;
constexpr int64_t BLOCK_SIZE = 32;
constexpr int64_t ALIGN_SIZE = 16;  // f16/bf16 对齐到32字节

template <HardEvent event>
__aicore__ inline void SetWaitFlag(HardEvent evt)
{
    event_t eventId = static_cast<event_t>(GetTPipePtr()->FetchEventID(evt));
    SetFlag<event>(eventId);
    WaitFlag<event>(eventId);
}

template <typename DTYPE>
class KernelAiInfraFusedCausalConv1dBase {
public:
    __aicore__ inline KernelAiInfraFusedCausalConv1dBase(TPipe *pipe, const AiInfraFusedCausalConv1dTilingData *tiling)
        : pipe_(pipe), tilingData_(tiling)
    {}

    __aicore__ inline int64_t FindBIdx(int64_t val)
    {
        int64_t left = 0;
        int64_t right = this->tilingData_->batchSize;
        while (left <= right) {
            int64_t mid = (left + right) / 2;
            int64_t temp = this->queryStartLocGm.GetValue(mid);
            if (temp > val) {
                right = mid - 1;
            } else if (temp < val) {
                left = mid + 1;
            } else {
                return mid;
            }
        }
        return right;
    }

protected:
    // Shared Constants to be removed
    int64_t baseDimIdx{0};
    int64_t baseblockFactorIdx{0};
    int64_t curBlockFactor{0};
    int64_t curBaseDim{0};
    int64_t tokenIdx{0};
    int64_t batchId{0};
    int64_t seqIdStart{0};
    int64_t seqIdEnd{0};
    int64_t seqId{0};
    int64_t seqLen{0};

    // Sahred members
