    const AiInfraFusedCausalConv1dTilingData *tilingData_;

    GlobalTensor<DTYPE> xGm, weightGm, convStateGm, outGm, BiasGm;
    GlobalTensor<int32_t> queryStartLocGm, cacheIndicesGm, hasInitialStateGm, numAcceptedTokensGm, numComputedTokensGm,
        blockIdxFirstScheduledTokenGm, blockIdxLastScheduledTokenGm, initialStateIdxGm;
};

}  // namespace AiInfraFusedCausalConv1d

#endif  // _AI_INFRA_FUSED_CAUSAL_CONV1D_COMMON_H_

