216	__aicore__ inline void Kernel::VectorBufferInit()
217	{
218	    pipe_.InitBuffer(stateBuf_, UB_STATE_SIZE);
219	    pipe_.InitBuffer(valueBuf_, UB_VALUE_SIZE);
220	    pipe_.InitBuffer(vNewOutBuf_, UB_VNEW_SIZE);
221	    mte3ToMte2V0[0] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
222	    mte3ToMte2V0[1] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
223	    mte3ToMte2V1[0] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
224	    mte3ToMte2V1[1] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
225	    mte2ToVV0[0] = pipe_.AllocEventID<HardEvent::MTE2_V>();
226	    mte2ToVV0[1] = pipe_.AllocEventID<HardEvent::MTE2_V>();
227	    mte2ToVV1[0] = pipe_.AllocEventID<HardEvent::MTE2_V>();
228	    mte2ToVV1[1] = pipe_.AllocEventID<HardEvent::MTE2_V>();
229	    vToMte3V0[0] = pipe_.AllocEventID<HardEvent::V_MTE3>();
230	    vToMte3V0[1] = pipe_.AllocEventID<HardEvent::V_MTE3>();
231	    vToMte3V1[0] = pipe_.AllocEventID<HardEvent::V_MTE3>();
232	    vToMte3V1[1] = pipe_.AllocEventID<HardEvent::V_MTE3>();
233	    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[0]);
234	    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[1]);
235	    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[0]);
236	    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[1]);
237	    stateTensor_ = stateBuf_.Get<float>();
238	    valueTensor_ = valueBuf_.Get<float>();
239	    vNewOutTensor_ = vNewOutBuf_.Get<float>();
240	}
241	
242	__aicore__ inline void Kernel::CubeBufferInit()
243	{
244	    CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_FIX>(SYNC_FLAG_C0V0);
245	    // L1A/L1B
246	    pipe_.InitBuffer(aBufL1_, L1A_SIZE);
247	    pipe_.InitBuffer(bBufL1_, L1B_SIZE);
248	    mte1ToMte2A[0] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
249	    mte1ToMte2A[1] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
250	    mte1ToMte2B[0] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
251	    mte1ToMte2B[1] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
252	    mte2ToMte1A[0] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
253	    mte2ToMte1A[1] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
254	    mte2ToMte1B[0] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
255	    mte2ToMte1B[1] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
256	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[0]);
257	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[1]);
258	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[0]);
259	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[1]);
260	    // fix <> mte2
261	    fixToMte2 = pipe_.AllocEventID<HardEvent::FIX_MTE2>();
262	    SetFlag<HardEvent::FIX_MTE2>(fixToMte2);
263	    aL1Tensor_ = aBufL1_.Get<float>();
264	    bL1Tensor_ = bBufL1_.Get<float>();
265	
266	    // L0A/L0B
267	    pipe_.InitBuffer(aBufL0_, L0A_SIZE);
268	    pipe_.InitBuffer(bBufL0_, L0B_SIZE);
269	    mToMte1A[0] = pipe_.AllocEventID<HardEvent::M_MTE1>();
270	    mToMte1A[1] = pipe_.AllocEventID<HardEvent::M_MTE1>();
271	    mToMte1B[0] = pipe_.AllocEventID<HardEvent::M_MTE1>();
272	    mToMte1B[1] = pipe_.AllocEventID<HardEvent::M_MTE1>();
273	    mte1ToMA[0] = pipe_.AllocEventID<HardEvent::MTE1_M>();
274	    mte1ToMA[1] = pipe_.AllocEventID<HardEvent::MTE1_M>();
275	    mte1ToMB[0] = pipe_.AllocEventID<HardEvent::MTE1_M>();
276	    mte1ToMB[1] = pipe_.AllocEventID<HardEvent::MTE1_M>();
277	    SetFlag<HardEvent::M_MTE1>(mToMte1A[0]);
278	    SetFlag<HardEvent::M_MTE1>(mToMte1A[1]);
279	    SetFlag<HardEvent::M_MTE1>(mToMte1B[0]);
280	    SetFlag<HardEvent::M_MTE1>(mToMte1B[1]);
281	    aL0Tensor_ = aBufL0_.Get<float>();
282	    bL0Tensor_ = bBufL0_.Get<float>();
283	    
284	    // L0C
285	    pipe_.InitBuffer(cBufL0_, L0C_SIZE);
286	    fixToM[0] = pipe_.AllocEventID<HardEvent::FIX_M>();
287	    fixToM[1] = pipe_.AllocEventID<HardEvent::FIX_M>();
288	    mToFix[0] = pipe_.AllocEventID<HardEvent::M_FIX>();
289	    mToFix[1] = pipe_.AllocEventID<HardEvent::M_FIX>();
290	    SetFlag<HardEvent::FIX_M>(fixToM[0]);
291	    SetFlag<HardEvent::FIX_M>(fixToM[1]);
292	    cL0Tensor_ = cBufL0_.Get<float>();
293	}
294	
295	__aicore__ inline void Kernel::Init(
296	        __gm__ uint8_t *initialState,
297	        __gm__ uint8_t *kgexp,
298	        __gm__ uint8_t *value,
299	        __gm__ uint8_t *kCumdecay,
300	        __gm__ uint8_t *qgexp,
301	        __gm__ uint8_t *gexp,
302	        __gm__ uint8_t *actualSeqlens,
303	        __gm__ uint8_t *attnInterOut,
304	        __gm__ uint8_t *vNewOut,
305	        __gm__ uint8_t *workspace,
306	        const TilingData *__restrict tilingData)
307	{
308	    PipeBarrier<PIPE_ALL>();
309	    blockIdx_ = GetBlockIdx();
310	    blockNum_ = GetBlockNum();
311	    params_ = tilingData;
312	    initialStateGm_.SetGlobalBuffer((__gm__ float*)initialState);
313	    kgexpGm_.SetGlobalBuffer((__gm__ float*)kgexp);
314	    valueGm_.SetGlobalBuffer((__gm__ float*)value);
315	    kCumdecayGm_.SetGlobalBuffer((__gm__ float*)kCumdecay);
316	    qgexpGm_.SetGlobalBuffer((__gm__ float*)qgexp);
317	    gexpGm_.SetGlobalBuffer((__gm__ float*)gexp);
318	    actualSeqlensGm_.SetGlobalBuffer((__gm__ int32_t*)actualSeqlens);
319	    attnInterOutGm_.SetGlobalBuffer((__gm__ float*)attnInterOut);
320	    vNewOutGm_.SetGlobalBuffer((__gm__ float*)vNewOut);
321	    if ASCEND_IS_AIV {
322	        VectorBufferInit();
323	    } else {
324	        CubeBufferInit();
325	    }
326	}
