328	template <bool enTranspose = false>
329	__aicore__ inline void Kernel::LoadDataToL0A(const LocalTensor<float>& aL0Tensor, const LocalTensor<float>& aL1Tensor,
330	    uint32_t fullSize, uint32_t kSplitSize, uint32_t mSplitSize)
331	{
332	    if constexpr (enTranspose) {
333	        // 对于 v_new_out.trans @ kgexp
334	        // v_new_out 的L1排布是 ZZ，而 v_new_out.trans 的排布是 NN，A矩阵的要求的排步是 ZZ，因此需要分型的转置
335	        LoadData2dTransposeParams loadData2dTransposeParams;
336	        loadData2dTransposeParams.startIndex = 0;
337	        loadData2dTransposeParams.srcStride = fullSize / fractionH;
338	        loadData2dTransposeParams.dstFracGap = 0;
339	        loadData2dTransposeParams.dstGap = 1;
340	        loadData2dTransposeParams.repeatTimes = kSplitSize / fractionH;
341	        uint32_t loopTimes = mSplitSize / fractionH;
342	        uint64_t l1Offset = fractionH * fractionH;
343	        uint64_t l0Offset = kSplitSize * fractionH;
344	        // 按行迭代
345	        for(uint32_t i = 0; i < loopTimes; i++) {
346	            LoadDataWithTranspose(aL0Tensor[i * l0Offset], aL1Tensor[i * l1Offset], loadData2dTransposeParams);
347	        }
348	    } else {
349	        // 对于 qgexp @ state.trans
350	        // qgexp 的排布是 ZZ，A矩阵的要求的排步是 ZZ，因此需要不需要分型的转置
351	        LoadData2DParams loadData2DParams;
352	        loadData2DParams.startIndex = 0;
353	        loadData2DParams.srcStride = 1;
354	        loadData2DParams.dstGap = 0;
355	        loadData2DParams.repeatTimes = (mSplitSize / fractionH) * (kSplitSize / fractionW);
356	        loadData2DParams.ifTranspose = false;
357	        LoadData(aL0Tensor, aL1Tensor, loadData2DParams);
358	    }
359	}
