361	template <bool enTranspose = false>
362	__aicore__ inline void Kernel::LoadDataToL0B(const LocalTensor<float>& bL0Tensor, const LocalTensor<float>& bL1Tensor,
363	    uint32_t fullSize, uint32_t kSplitSize, uint32_t nSplitSize)
364	{
365	    if constexpr (enTranspose) {
366	        // 对于 qgexp @ state.trans
367	        // state 的排布是 NZ，而 state.trans 的排布是 ZN，B矩阵的要求是ZN，不需要转置，直接最简单拷贝就行
368	        LoadData2DParams loadData2DParams;
369	        loadData2DParams.startIndex = 0;
370	        loadData2DParams.srcStride = 1;
371	        loadData2DParams.dstGap = 0;
372	        loadData2DParams.ifTranspose = false;
373	        if(fullSize == nSplitSize) { // 直接完整拷贝即可
374	            loadData2DParams.repeatTimes = ((nSplitSize + fractionH - 1) / fractionH) * (kSplitSize / fractionW);
375	            LoadData(bL0Tensor, bL1Tensor, loadData2DParams);
376	        } else { // 需要处理截断
377	            loadData2DParams.repeatTimes = (nSplitSize + fractionH - 1) / fractionH;
378	            uint32_t loopTimes = kSplitSize / fractionW;
379	            uint64_t l1Offset = fullSize * fractionW;
380	            uint64_t l0Offset = nSplitSize * fractionW;
381	            for (uint32_t i = 0; i < loopTimes; i++) {
382	                LoadData(bL0Tensor[i * l0Offset], bL1Tensor[i * l1Offset], loadData2DParams);
383	            }
384	        }
385	    } else {
386	        // 对于 v_new_out.trans @ kgexp
387	        // kgexp 的排布是 ZZ，B矩阵的要求的排步是 ZN，因此需要需要分型做转置
388	        LoadData2dTransposeParams loadData2dTransposeParams;
389	        loadData2dTransposeParams.startIndex = 0;
390	        loadData2dTransposeParams.srcStride = fullSize / fractionH;
391	        loadData2dTransposeParams.dstFracGap = nSplitSize / fractionH - 1;
392	        loadData2dTransposeParams.dstGap = 2 * nSplitSize / fractionH - 1;
393	        loadData2dTransposeParams.repeatTimes = kSplitSize / fractionH;
394	        // 按照列迭代
395	        uint32_t loopTimes = nSplitSize / fractionH;
396	        uint64_t l1Offset = fractionH * fractionH;
397	        uint64_t l0Offset = fractionH * fractionH;
398	        for(uint32_t i = 0; i < loopTimes; i++) {
399	            LoadDataWithTranspose(bL0Tensor[i * l0Offset], bL1Tensor[i * l1Offset], loadData2dTransposeParams);
400	        }
401	    }
402	}
