451	        nd2nzPara.nValue = m;
452	        nd2nzPara.dValue = n;
453	        nd2nzPara.srcDValue = n;
454	        nd2nzPara.dstNzC0Stride = m;
455	        nd2nzPara.dstNzNStride = 1;
456	        nd2nzPara.srcNdMatrixStride = 0;
457	        nd2nzPara.dstNzMatrixStride = 0;
