462	template<bool enableZZ = true, bool splitM = false>
463	__aicore__ inline int32_t Kernel::LoadL1A(const GlobalTensor<float> &gm, uint32_t m, uint32_t k,
464	    uint32_t mStart, uint32_t mEnd)
465	{
