470	    if constexpr (splitM) {
471	        LoadDataToL1<enableZZ>(aL1Tensor_[l1Offset + mStart * k], gm[mStart * k], mEnd - mStart, k);
472	    } else {
473	        LoadDataToL1<enableZZ>(aL1Tensor_[l1Offset], gm, m, k);
474	    }
475	    SetFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[curL1Iter & 1]);
476	    cubeL1AIter++;
477	    return curL1Iter;
