493	template <bool enBTranspose = true>
494	__aicore__ inline void Kernel::MatmulIterN(const LocalTensor<float> &cL0,
495	    const LocalTensor<float> &aL0, const LocalTensor<float> &bL1, uint32_t m, uint32_t k, uint32_t n)
496	{
497	    uint32_t nLoop = n / baseN;
498	    MmadParams mmadParams;
499	    mmadParams.m = m;
500	    mmadParams.n = baseN;
501	    mmadParams.k = k;
502	    mmadParams.unitFlag = 0;
503	    mmadParams.cmatrixInitVal = true;
504	    for (uint32_t nIter = 0; nIter < nLoop; nIter++) { // 切核场景，需要进行修改
505	        // 载入 L0B
506	        int32_t l0BCurIter = 0;
507	        if constexpr (enBTranspose) {
508	            // NZ -> ZN
509	            l0BCurIter = LoadDataL0B<true>(bL1[nIter * fractionW * baseN], n, k, baseN);
510	        } else {
511	            // ZZ -> ZN
512	            l0BCurIter = LoadDataL0B<false>(bL1[nIter * fractionH * baseN], n, k, baseN);
513	        }
514	        size_t bL0Offset = (l0BCurIter & 1) * (L0B_PP_SIZE >> 2);
515	        // 计算 mmad
516	        WaitFlag<HardEvent::MTE1_M>(mte1ToMB[l0BCurIter & 1]);
517	        Mmad(cL0[nIter * m * baseN], aL0, bL0Tensor_[bL0Offset], mmadParams);
518	        SetFlag<HardEvent::M_MTE1>(mToMte1B[l0BCurIter & 1]);
519	    }
520	}
