522	template<bool enATranspose = false, bool enBTranspose = true, bool enAtomicAdd = false>
523	__aicore__ inline void Kernel::MatmulSplitM(const GlobalTensor<float> &out, const LocalTensor<float> &aL1,
524	    const LocalTensor<float> &bL1, uint32_t m, uint32_t k, uint32_t n, uint32_t mStart, uint32_t mEnd)
525	{
526	    FixpipeParamsV220 fixParams;
527	    fixParams.nSize = n;
528	    fixParams.mSize = baseM;
529	    fixParams.srcStride = baseM;
530	    fixParams.dstStride = n;
531	    fixParams.ndNum = 1;
532	    fixParams.unitFlag = 0;
533	    mStart /= baseM;
534	    mEnd /= baseM;
535	    for (uint32_t i = mStart; i < mEnd; i++) {
536	        // L1(ZZ/NN) -> L0A(ZZ), 因此需要 i * baseM * fractionW 的偏移量
537	        int32_t l0ACurIter = 0;
538	        if constexpr (enATranspose) {
539	            // NN->ZZ
540	            l0ACurIter = LoadDataL0A<true>(aL1[i * baseM * fractionH], m, k, baseM);
541	        } else {
542	            // ZZ->ZZ
543	            l0ACurIter = LoadDataL0A<false>(aL1[i * baseM * k], m, k, baseM);
544	        }
545	        size_t aL0Offset = (l0ACurIter & 1) * (L0A_PP_SIZE >> 2);
546	        size_t cL0Offset = (cubeL0CIter & 1) * (L0C_PP_SIZE >> 2);
547	        // 切核此处要变 bL1 偏移量
548	        WaitFlag<HardEvent::FIX_M>(fixToM[cubeL0CIter & 1]);
549	        WaitFlag<HardEvent::MTE1_M>(mte1ToMA[l0ACurIter & 1]);
550	        MatmulIterN<enBTranspose>(cL0Tensor_[cL0Offset], aL0Tensor_[aL0Offset], bL1, baseM, k, n);
551	        SetFlag<HardEvent::M_MTE1>(mToMte1A[l0ACurIter & 1]);
552	        SetFlag<HardEvent::M_FIX>(mToFix[cubeL0CIter & 1]);
553	        // 矩阵乘法计算完成，允许fix_pipe开始搬运
554	        WaitFlag<HardEvent::M_FIX>(mToFix[cubeL0CIter & 1]);
555	        // 搬运到 GM（或者 atomic_add)
556	        if constexpr (enAtomicAdd) {
557	            SetAtomicAdd<float>();
558	        }
559	        Fixpipe(out[i * baseM * n], cL0Tensor_[cL0Offset], fixParams); // 切核此处要变out偏移量
560	        if constexpr (enAtomicAdd) {
561	            SetAtomicNone();
562	        }
563	        // fix_pipe搬运完成，允许矩阵乘法
564	        SetFlag<HardEvent::FIX_M>(fixToM[cubeL0CIter & 1]);
565	        cubeL0CIter++;
566	    }
567	}
