581	template<bool splitM = false>
582	__aicore__ inline void Kernel::SingleChunkCubeProcessC0(const GlobalTensor<float> &state,
583	    const GlobalTensor<float> &kCumdecay)
584	{
585	    // 载入 kCumdecay (ZZ) 到 L1A
586	    uint32_t mStart = 0;
587	    uint32_t mEnd = 0;
588	    GetMRange<splitM>(mStart, mEnd, params_->chunkSize);
589	    kCumdecayIter = LoadL1A<true, splitM>(kCumdecay, params_->chunkSize, params_->kDim, mStart, mEnd);
590	    // 等待上一轮 state 更新完毕，才能拷贝 state（切分场景需要全核同步）
591	    if constexpr (splitM) {
592	        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C0V0);
593	    } else {
594	        WaitFlag<HardEvent::FIX_MTE2>(fixToMte2);
595	    }
596	    // 载入 state (NZ)
597	    stateIter = LoadL1B<false>(state, params_->vDim, params_->kDim);
598	}
