600	template<bool splitM = false>
601	__aicore__ inline void Kernel::SingleChunkCubeProcessC1(const GlobalTensor<float> &vNewOut,
602	    const GlobalTensor<float> &qgexp, const GlobalTensor<float> &kgexp)
603	{
604	    // 载入  qgexp (ZZ) 到 L1A
605	    uint32_t mStart = 0;
606	    uint32_t mEnd = 0;
607	    GetMRange<splitM>(mStart, mEnd, params_->chunkSize);
608	    qgexpIter = LoadL1A<true, splitM>(qgexp, params_->chunkSize, params_->kDim, mStart, mEnd);
609	    // 载入 kgexp (ZZ) 到 L1B
610	    kgexpIter = LoadL1B(kgexp, params_->chunkSize, params_->kDim);
611	    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1B[stateIter & 1]);
612	    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[kCumdecayIter & 1]);
613	    // 计算 vNewOut = kCumdecay @ state.trans
614	    MatmulSplitM(vNewOut, aL1Tensor_[(kCumdecayIter & 1) * (L1A_PP_SIZE >> 2)],
615	        bL1Tensor_[(stateIter & 1) * (L1B_PP_SIZE >> 2)],
616	        params_->chunkSize, params_->kDim, params_->vDim, mStart, mEnd);
617	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[kCumdecayIter & 1]);
618	}
