620	template<bool splitM = false>
621	__aicore__ inline void Kernel::SingleChunkCubeProcessC2(const GlobalTensor<float> &attnInterOut)
622	{
623	    // 计算 attnIterOut = qgexp @ state.trans
624	    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[qgexpIter & 1]);
625	    uint32_t mStart = 0;
626	    uint32_t mEnd = 0;
627	    GetMRange<splitM>(mStart, mEnd, params_->chunkSize);
628	    MatmulSplitM(attnInterOut, aL1Tensor_[(qgexpIter & 1) * (L1A_PP_SIZE >> 2)],
629	        bL1Tensor_[(stateIter & 1) * (L1B_PP_SIZE >> 2)],
630	        params_->chunkSize, params_->kDim, params_->vDim, mStart, mEnd);
631	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[qgexpIter & 1]);
632	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[stateIter & 1]);
633	}
