635	template<bool splitM = false>
636	__aicore__ inline void Kernel::SingleChunkCubeProcessC3(const GlobalTensor<float> &state,
637	    const GlobalTensor<float> &vNewOut)
638	{
639	    // 全载 vNewOut GM -> L1A -> L0A（L1B 已经载入 kgexp）
640	    vNewOutIter = LoadL1A<true, false>(vNewOut, params_->chunkSize, params_->vDim, 0, params_->chunkSize);
641	    // 计算 initial_state += v_new_out.trans @ state（A转置+B不转置+AtomicAdd）
642	    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1B[kgexpIter & 1]);
643	    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[vNewOutIter & 1]);
644	    uint32_t mStart = 0;
645	    uint32_t mEnd = 0;
646	    GetMRange<splitM>(mStart, mEnd, params_->vDim);
647	    MatmulSplitM<true, false, true>(state, aL1Tensor_[(vNewOutIter & 1) * (L1A_PP_SIZE >> 2)],
648	        bL1Tensor_[(kgexpIter & 1) * (L1B_PP_SIZE >> 2)],
649	        params_->vDim, params_->chunkSize, params_->kDim, mStart, mEnd);
650	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[vNewOutIter & 1]);
651	    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[kgexpIter & 1]);
652	    if constexpr (splitM) {
653	        // 切 M 场景需要做全核同步
654	        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_FIX>(SYNC_FLAG_C0V0);
655	    } else {
656	        // 不切 M 的话只需要单核同步即可
657	        SetFlag<HardEvent::FIX_MTE2>(fixToMte2);
658	    }
659	}
