661	template<bool splitM = false>
662	__aicore__ inline void Kernel::SingleChunkCubeProcess(
663	    const GlobalTensor<float> &state, const GlobalTensor<float> &attnInterOut, const GlobalTensor<float> &vNewOut,
664	    const GlobalTensor<float> &kgexp, const GlobalTensor<float> &kCumdecay, const GlobalTensor<float> &qgexp)
665	{
666	    SingleChunkCubeProcessC0<splitM>(state, kCumdecay);
667	    // C0 拷贝完，向 V0 同步
668	    CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C0V0);
669	    SingleChunkCubeProcessC1<splitM>(vNewOut, qgexp, kgexp);
670	    // C1 结束向 V1 同步
671	    CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_FIX>(SYNC_FLAG_C1V1);
672	    SingleChunkCubeProcessC2<splitM>(attnInterOut);
673	    // C3 等待 V1 (等待 vNewOut ready)
674	    CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_V1C3);
675	    SingleChunkCubeProcessC3<splitM>(state, vNewOut);
676	}
