678	__aicore__ inline void Kernel::SingleChunkVecProcessV0(const GlobalTensor<float> &state,
679	    float gexp, size_t size)
680	{
681	    constexpr size_t baseSize = 1024; // 4 KB，当前较好的拷贝大小
682	    size_t iterCount = size / baseSize;
683	    for (size_t i = 0; i < iterCount; i++) {
684	        size_t v0Offset = (vec0Iter & 1) * (UB_STATE_PP_SIZE >> 2);
685	        // CopyIn
686	        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[vec0Iter & 1]);
687	        DataCopy(stateTensor_[v0Offset], state[i * baseSize], baseSize);
688	        SetFlag<HardEvent::MTE2_V>(mte2ToVV0[vec0Iter & 1]);
689	        // Compute
690	        WaitFlag<HardEvent::MTE2_V>(mte2ToVV0[vec0Iter & 1]);
691	        Muls(stateTensor_[v0Offset], stateTensor_[v0Offset], gexp, baseSize);
692	        SetFlag<HardEvent::V_MTE3>(vToMte3V0[vec0Iter & 1]);
693	        // CopyOut
694	        WaitFlag<HardEvent::V_MTE3>(vToMte3V0[vec0Iter & 1]);
695	        DataCopy(state[i * baseSize], stateTensor_[v0Offset], baseSize);
696	        SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[vec0Iter & 1]);
697	        vec0Iter++;
698	    }
699	}
