701	__aicore__ inline void Kernel::SingleChunkVecProcessV1(const GlobalTensor<float> &vNewOut,
702	    const GlobalTensor<float> &value, size_t size)
703	{
704	    constexpr size_t baseSize = 1024; // 4 KB，暂定拷贝大小
705	    size_t iterCount = size / baseSize;
706	    for (size_t i = 0; i < iterCount; i++) {
707	        size_t v1Offset = (vec1Iter & 1) * (UB_STATE_PP_SIZE >> 2);
708	        // CopyIn
709	        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[vec1Iter & 1]);
710	        DataCopy(valueTensor_[v1Offset], value[i * baseSize], baseSize);
711	        DataCopy(vNewOutTensor_[v1Offset], vNewOut[i * baseSize], baseSize);
712	        SetFlag<HardEvent::MTE2_V>(mte2ToVV1[vec1Iter & 1]);
713	        // Compute
714	        WaitFlag<HardEvent::MTE2_V>(mte2ToVV1[vec1Iter & 1]);
715	        Sub(valueTensor_[v1Offset], valueTensor_[v1Offset], vNewOutTensor_[v1Offset], baseSize);
716	        SetFlag<HardEvent::V_MTE3>(vToMte3V1[vec1Iter & 1]);
717	        // CopyOut
718	        WaitFlag<HardEvent::V_MTE3>(vToMte3V1[vec1Iter & 1]);
719	        DataCopy(vNewOut[i * baseSize], valueTensor_[v1Offset], baseSize);
720	        SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[vec1Iter & 1]);
721	        vec1Iter++;
722	    }
723	}
