725	template<bool splitM = false>
726	__aicore__ inline void Kernel::SingleChunkVecProcess(
727	    const GlobalTensor<float> &state, const GlobalTensor<float> &vNewOut, const GlobalTensor<float> &value, float gexp)
728	{
729	    // V0 需要同步 C0
730	    uint32_t sOffset = 0;
731	    uint32_t sLength = params_->kDim * params_->vDim;
732	    if constexpr (splitM) {
733	        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C0V0);
734	        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C0V0);
735	        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C0V0);
736	        sLength /= params_->mSplitNum;
737	        sOffset = sLength * (blockIdx_ % params_->mSplitNum);
738	    } else {
739	        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C0V0);
740	    }
741	    SingleChunkVecProcessV0(state[sOffset], gexp, sLength);
742	    // V1 需要同步 C1
743	    uint32_t vOffset = 0;
744	    uint32_t vLength = params_->chunkSize * params_->vDim;
745	    if constexpr (splitM) {
746	        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C1V1);
747	        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C1V1);
748	        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C1V1);
749	        vLength /= params_->mSplitNum;
750	        vOffset = vLength * (blockIdx_ % params_->mSplitNum);
751	    } else {
752	        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C1V1);
753	    }
754	    SingleChunkVecProcessV1(vNewOut[vOffset], value[vOffset], vLength);
755	    // V1 结束，需要同步 C3
756	    if constexpr (splitM) {
757	        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_MTE3>(SYNC_FLAG_V1C3);
758	        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE3>(SYNC_FLAG_V1C3);
759	        CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE3>(SYNC_FLAG_V1C3);
760	    } else {
761	        CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE3>(SYNC_FLAG_V1C3);
762	    }
763	}
764	
765	template<bool splitM = false>
766	__aicore__ inline void Kernel::SingleBatchProcess(
767	    uint32_t curBatch, uint32_t curHead, uint64_t seqStartChunk, uint64_t seqEndChunk)
768	{
769	    if constexpr (splitM) {
770	        // head+msplit核间并行
771	        if (curHead % (blockNum_ / params_->mSplitNum) != (blockIdx_ / params_->mSplitNum)) {
772	            return;
773	        }
774	    } else {
775	        // batch+head核间并行
776	        if ((curBatch * params_->headNum + curHead) % blockNum_ != blockIdx_) {
777	            return;
778	        }
779	    }
780	    size_t chunkOffset = curHead * params_->chunkNum + seqStartChunk;
781	    // [b, hv, dk, dv]
782	    size_t sOffset = (curBatch * params_->headNum + curHead) * params_->kDim * params_->vDim;
783	    // [hv, n_chunk, chunk_size, dk]
784	    size_t kOffset = chunkOffset * params_->chunkSize * params_->kDim;
785	    // [hv, n_chunk, chunk_size, dv]
786	    size_t vOffset = chunkOffset * params_->chunkSize * params_->vDim;
787	    // [hv, n_chunk, chunk_size, 1] 取最后一个值
788	    size_t gOffset = (chunkOffset + 1) * params_->chunkSize - 1;
789	    for (uint64_t i = seqStartChunk; i < seqEndChunk; i++) {
790	        if ASCEND_IS_AIV {
791	            // [hv, n_chunk, chunk_size, 1] 最后一个
792	            float gexp = gexpGm_.GetValue(gOffset);
793	            SingleChunkVecProcess<splitM>(initialStateGm_[sOffset], vNewOutGm_[vOffset], valueGm_[vOffset], gexp);
794	        } else {
795	            SingleChunkCubeProcess<splitM>(initialStateGm_[sOffset], attnInterOutGm_[vOffset], vNewOutGm_[vOffset],
796	                kgexpGm_[kOffset], kCumdecayGm_[kOffset], qgexpGm_[kOffset]);
797	        }
798	        kOffset += params_->chunkSize * params_->kDim;
799	        vOffset += params_->chunkSize * params_->vDim;
800	        gOffset += params_->chunkSize;
801	    }
802	}
803	
804	template<bool splitM = false>
805	__aicore__ inline void Kernel::RunProcess()
806	{
807	    int32_t seqStartChunk = 0;
808	    for (uint32_t curBatch = 0; curBatch  < params_->batchNum; curBatch++) {
809	        int32_t seqLen = actualSeqlensGm_.GetValue((size_t)curBatch);
810	        if (unlikely(seqLen < 0)) {
811	            assert(false, "elements in actual_seqlens must be >= 0!\n");
812	            Trap();
813	            return;
814	        }
815	        if (unlikely(seqLen % params_->chunkSize != 0)) {
816	            assert(false, "elements in actual_seqlens must be divied by chunk_size!\n");
817	            Trap();
818	            return;
819	        }
820	        int32_t seqEndChunk = seqStartChunk + seqLen / params_->chunkSize;
821	        if (seqEndChunk > params_->chunkNum) {
822	            assert(false, "sum of actual_seqlens must equals to n_chunks!\n");
823	            Trap();
824	            return;
825	        }
826	        for (uint32_t curHead = 0; curHead < params_->headNum; curHead++) {
827	            SingleBatchProcess<splitM>(curBatch, curHead, seqStartChunk, seqEndChunk);
828	        }
829	        seqStartChunk = seqEndChunk;
830	    }
831	}
832	
833	__aicore__ inline void Kernel::Process()
834	{
835	    if (params_->enableMSplit) {
836	        RunProcess<true>();
837	    } else {
838	        RunProcess<false>();
839	    }
840	    if ASCEND_IS_AIC {
841	        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[0]);
842	        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[1]);
843	        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[0]);
844	        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[1]);
845	
846	        WaitFlag<HardEvent::M_MTE1>(mToMte1A[0]);
847	        WaitFlag<HardEvent::M_MTE1>(mToMte1A[1]);
848	        WaitFlag<HardEvent::M_MTE1>(mToMte1B[0]);
849	        WaitFlag<HardEvent::M_MTE1>(mToMte1B[1]);
850	
851	        WaitFlag<HardEvent::FIX_M>(fixToM[0]);
852	        WaitFlag<HardEvent::FIX_M>(fixToM[1]);
853	
854	        WaitFlag<HardEvent::FIX_MTE2>(fixToMte2);
855	    } else {
856	        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[0]);
857	        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[1]);
858	        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[0]);
859	        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[1]);
860	    }
861	    PipeBarrier<PIPE_ALL>();
862	}
863	
864	}

