/*!
 * \file chunk_gated_delta_rule_recurrence_kernel.h
 * \brief
 */

#include "kernel_operator.h"
#include "kernel_operator_list_tensor_intf.h"
#include "kernel_tiling/kernel_tiling.h"
#include "lib/matmul_intf.h"
#include "lib/matrix/matmul/tiling.h"
#include "chunk_gated_delta_rule_recurrence_tilingdata.h"

namespace ChunkGatedDeltaRuleRecurrence {

using TilingData = optiling::ChunkGatedDeltaRuleRecurrenceTilingData;

using namespace AscendC;
class Kernel {
public:
    __aicore__ inline void Init(
        __gm__ uint8_t *initialState,
        __gm__ uint8_t *kgexp,
        __gm__ uint8_t *value,
        __gm__ uint8_t *kCumdecay,
        __gm__ uint8_t *qgexp,
        __gm__ uint8_t *gexp,
        __gm__ uint8_t *actualSeqlens,
        __gm__ uint8_t *attnInterOut,
        __gm__ uint8_t *vNewOut,
        __gm__ uint8_t *workspace,
        const TilingData *__restrict tilingData
    );
    __aicore__ inline void Process();
private:
    const TilingData *params_;
    TPipe pipe_;
    uint32_t blockIdx_ = 0U;
    uint32_t subIdx = 0U;
    uint32_t blockNum_ = 0U;
    GlobalTensor<float> initialStateGm_;
    GlobalTensor<float> kgexpGm_;
    GlobalTensor<float> valueGm_;
    GlobalTensor<float> kCumdecayGm_;
    GlobalTensor<float> qgexpGm_;
    GlobalTensor<float> gexpGm_;
    GlobalTensor<int32_t> actualSeqlensGm_;
    GlobalTensor<float> attnInterOutGm_;
    GlobalTensor<float> vNewOutGm_;

    TBuf<TPosition::A1> aBufL1_;
    TBuf<TPosition::B1> bBufL1_;
    LocalTensor<float> aL1Tensor_;
    LocalTensor<float> bL1Tensor_;
    LocalTensor<float> aL0Tensor_;
    LocalTensor<float> bL0Tensor_;
    LocalTensor<float> cL0Tensor_;
    TBuf<TPosition::A2> aBufL0_;
    TBuf<TPosition::B2> bBufL0_;
    TBuf<TPosition::CO1> cBufL0_;

    static constexpr uint16_t SYNC_FLAG_C0V0 = 6;
    static constexpr uint16_t SYNC_FLAG_C1V1 = 7;
    static constexpr uint16_t SYNC_FLAG_V1C3 = 8;

    static constexpr uint32_t LOAD_DATA_UNIT = 512U;
    static constexpr uint32_t UNIT_FLAG_DISABLE = 0;
    static constexpr uint32_t L1A_SIZE = 256 * 1024; // 256 x 1024 (256KB)
    static constexpr uint32_t L1B_SIZE = 256 * 1024; // 256 x 1024 (256KB)
    static constexpr uint32_t L0A_SIZE = 64 * 1024;  // 64  x 1024 (64KB)
    static constexpr uint32_t L0B_SIZE = 64 * 1024;  // 64  x 1024 (64KB)
    static constexpr uint32_t L0C_SIZE = 128 * 1024; // 128 x 1024 (128KB)

    static constexpr uint32_t L1A_PP_SIZE = 128 * 1024; // 128 x 1024 (128KB)
    static constexpr uint32_t L1B_PP_SIZE = 128 * 1024; // 128 x 1024 (128KB)
    static constexpr uint32_t L0A_PP_SIZE = 32 * 1024;  // 32  x 1024 (32KB)
    static constexpr uint32_t L0B_PP_SIZE = 32 * 1024;  // 32  x 1024 (32KB)
    static constexpr uint32_t L0C_PP_SIZE = 64 * 1024;  // 64  x 1024 (64KB)

    TBuf<TPosition::VECCALC> stateBuf_;
    TBuf<TPosition::VECCALC> valueBuf_;
    TBuf<TPosition::VECCALC> vNewOutBuf_;
    LocalTensor<float> stateTensor_;
    LocalTensor<float> valueTensor_;
    LocalTensor<float> vNewOutTensor_;

    static constexpr uint32_t UB_STATE_SIZE = 64 * 1024; // 128 x 1024 (128KB)
    static constexpr uint32_t UB_VALUE_SIZE = 64 * 1024;  // 32  x 1024 (32KB)
    static constexpr uint32_t UB_VNEW_SIZE =  64 * 1024;  // 32  x 1024 (32KB)
    static constexpr uint32_t UB_STATE_PP_SIZE = 32 * 1024; // 32 x 1024 (32KB)
    static constexpr uint32_t UB_VALUE_PP_SIZE = 32 * 1024; // 32 x 1024 (32KB)
    static constexpr uint32_t UB_VNEW_PP_SIZE =  32 * 1024; // 32 x 1024 (32KB)

    static constexpr int SYNC_MODE_ALL = 0;      // 0 为同类型全核同步
    static constexpr int SYNC_MODE_CUBE_VEC = 2; // 2 为 group 内 CUBE 与 VEC 同步

    uint32_t cubeL1AIter = 0;
    uint32_t cubeL0AIter = 0;
    uint32_t cubeL1BIter = 0;
    uint32_t cubeL0BIter = 0;
    uint32_t cubeL0CIter = 0;

    uint32_t stateIter = 0;
    uint32_t kgexpIter = 0;

    uint32_t kCumdecayIter = 0;
    uint32_t qgexpIter = 0;
    uint32_t vNewOutIter = 0;

    uint32_t vec0Iter = 0;
    uint32_t vec1Iter = 0;

    static constexpr uint32_t fractionH = 16;                 // 分型高度 16 个元素
    static constexpr uint32_t fractionW = 32 / sizeof(float); // 分型宽度 32B
    static constexpr uint32_t baseM = fractionH;
    static constexpr uint32_t baseN = fractionH;

    // mte2 <> mte1
    int32_t mte2ToMte1A[2];
    int32_t mte2ToMte1B[2];
    int32_t mte1ToMte2A[2];
    int32_t mte1ToMte2B[2];

    // m <> mte1
    int32_t mToMte1A[2];
    int32_t mToMte1B[2];
    int32_t mte1ToMA[2];
    int32_t mte1ToMB[2];

    // fix <> m
    int32_t fixToM[2];
    int32_t mToFix[2];
    int32_t fixToMte2 = 0;

    // MTE2/MTE3 <> V
    int32_t mte3ToMte2V0[2];
    int32_t mte3ToMte2V1[2];
    int32_t mte2ToVV0[2];
    int32_t mte2ToVV1[2];
    int32_t vToMte3V0[2];
    int32_t vToMte3V1[2];

    __aicore__ inline void VectorBufferInit();
    __aicore__ inline void CubeBufferInit();

    template <bool enTranspose>
    __aicore__ inline void LoadDataToL0A(const LocalTensor<float>& aL0Tensor, const LocalTensor<float>& aL1Tensor,
        uint32_t fullSize, uint32_t kSplitSize, uint32_t mSplitSize);
    template <bool enTranspose>
    __aicore__ inline void LoadDataToL0B(const LocalTensor<float>& bL0Tensor, const LocalTensor<float>& bL1Tensor,
        uint32_t fullSize, uint32_t kSplitSize, uint32_t nSplitSize);
    template <bool enTranspose>
    __aicore__ inline int32_t LoadDataL0A(const LocalTensor<float>& aL1Tensor,
        uint32_t fullSize, uint32_t kSplitSize, uint32_t mSplitSize);
    template <bool enTranspose>
    __aicore__ inline int32_t LoadDataL0B(const LocalTensor<float>& bL1Tensor,
        uint32_t fullSize, uint32_t kSplitSize, uint32_t nSplitSize);
    template<bool enableZZ>
    __aicore__ inline void LoadDataToL1(const LocalTensor<float>& l1Tensor,
        const GlobalTensor<float>& gmTensor, uint32_t m, uint32_t n);
    template<bool enableZZ, bool splitM>
    __aicore__ inline int32_t LoadL1A(const GlobalTensor<float> &gm, uint32_t m, uint32_t k,
        uint32_t mStart, uint32_t mEnd);
    template<bool enableZZ>
    __aicore__ inline int32_t LoadL1B(const GlobalTensor<float> &gm, uint32_t k, uint32_t n);
    template <bool enBTranspose>
    __aicore__ inline void MatmulIterN(const LocalTensor<float> &cL0,
        const LocalTensor<float> &aL0, const LocalTensor<float> &bL1, uint32_t m, uint32_t k, uint32_t n);
    template<bool enATranspose, bool enBTranspose, bool enAtomicAdd>
    __aicore__ inline void MatmulSplitM(const GlobalTensor<float> &out, const LocalTensor<float> &aL1,
        const LocalTensor<float> &bL1, uint32_t m, uint32_t k, uint32_t n, uint32_t mStart, uint32_t mEnd);
    template<bool splitM>
    __aicore__ inline void GetMRange(uint32_t &mStart, uint32_t &mEnd, uint32_t mLength);
    template<bool splitM>
    __aicore__ inline void SingleChunkCubeProcessC0(const GlobalTensor<float> &state,
        const GlobalTensor<float> &kCumdecay);
    template<bool splitM>
    __aicore__ inline void SingleChunkCubeProcessC1(const GlobalTensor<float> &vNewOut,
        const GlobalTensor<float> &qgexp, const GlobalTensor<float> &kgexp);
    template<bool splitM>
    __aicore__ inline void SingleChunkCubeProcessC2(const GlobalTensor<float> &attnInterOut);
    template<bool splitM>
    __aicore__ inline void SingleChunkCubeProcessC3(const GlobalTensor<float> &state,
        const GlobalTensor<float> &vNewOut);
    template<bool splitM>
    __aicore__ inline void SingleChunkCubeProcess(
        const GlobalTensor<float> &state,
        const GlobalTensor<float> &attnInterOut,
        const GlobalTensor<float> &vNewOut,
        const GlobalTensor<float> &kgexp,
        const GlobalTensor<float> &kCumdecay,
        const GlobalTensor<float> &qgexp);
    __aicore__ inline void SingleChunkVecProcessV0(const GlobalTensor<float> &state,
        float gexp, size_t size);
    __aicore__ inline void SingleChunkVecProcessV1(const GlobalTensor<float> &vNewOut,
        const GlobalTensor<float> &value, size_t size);
    template<bool splitM>
    __aicore__ inline void SingleChunkVecProcess(const GlobalTensor<float> &state, const GlobalTensor<float> &vNewOut,
        const GlobalTensor<float> &value, float gexp);
    template<bool splitM>
    __aicore__ inline void SingleBatchProcess(
        uint32_t curBatch, uint32_t curHead, uint64_t seqStartChunk, uint64_t seqEndChunk);
    template<bool splitM>
    __aicore__ inline void RunProcess();
};

__aicore__ inline void Kernel::VectorBufferInit()
{
    pipe_.InitBuffer(stateBuf_, UB_STATE_SIZE);
    pipe_.InitBuffer(valueBuf_, UB_VALUE_SIZE);
    pipe_.InitBuffer(vNewOutBuf_, UB_VNEW_SIZE);
    mte3ToMte2V0[0] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
    mte3ToMte2V0[1] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
    mte3ToMte2V1[0] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
    mte3ToMte2V1[1] = pipe_.AllocEventID<HardEvent::MTE3_MTE2>();
    mte2ToVV0[0] = pipe_.AllocEventID<HardEvent::MTE2_V>();
    mte2ToVV0[1] = pipe_.AllocEventID<HardEvent::MTE2_V>();
    mte2ToVV1[0] = pipe_.AllocEventID<HardEvent::MTE2_V>();
    mte2ToVV1[1] = pipe_.AllocEventID<HardEvent::MTE2_V>();
    vToMte3V0[0] = pipe_.AllocEventID<HardEvent::V_MTE3>();
    vToMte3V0[1] = pipe_.AllocEventID<HardEvent::V_MTE3>();
    vToMte3V1[0] = pipe_.AllocEventID<HardEvent::V_MTE3>();
    vToMte3V1[1] = pipe_.AllocEventID<HardEvent::V_MTE3>();
    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[0]);
    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[1]);
    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[0]);
    SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[1]);
    stateTensor_ = stateBuf_.Get<float>();
    valueTensor_ = valueBuf_.Get<float>();
    vNewOutTensor_ = vNewOutBuf_.Get<float>();
}

__aicore__ inline void Kernel::CubeBufferInit()
{
    CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_FIX>(SYNC_FLAG_C0V0);
    // L1A/L1B
    pipe_.InitBuffer(aBufL1_, L1A_SIZE);
    pipe_.InitBuffer(bBufL1_, L1B_SIZE);
    mte1ToMte2A[0] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
    mte1ToMte2A[1] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
    mte1ToMte2B[0] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
    mte1ToMte2B[1] = pipe_.AllocEventID<HardEvent::MTE1_MTE2>();
    mte2ToMte1A[0] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
    mte2ToMte1A[1] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
    mte2ToMte1B[0] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
    mte2ToMte1B[1] = pipe_.AllocEventID<HardEvent::MTE2_MTE1>();
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[0]);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[1]);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[0]);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[1]);
    // fix <> mte2
    fixToMte2 = pipe_.AllocEventID<HardEvent::FIX_MTE2>();
    SetFlag<HardEvent::FIX_MTE2>(fixToMte2);
    aL1Tensor_ = aBufL1_.Get<float>();
    bL1Tensor_ = bBufL1_.Get<float>();

    // L0A/L0B
    pipe_.InitBuffer(aBufL0_, L0A_SIZE);
    pipe_.InitBuffer(bBufL0_, L0B_SIZE);
    mToMte1A[0] = pipe_.AllocEventID<HardEvent::M_MTE1>();
    mToMte1A[1] = pipe_.AllocEventID<HardEvent::M_MTE1>();
    mToMte1B[0] = pipe_.AllocEventID<HardEvent::M_MTE1>();
    mToMte1B[1] = pipe_.AllocEventID<HardEvent::M_MTE1>();
    mte1ToMA[0] = pipe_.AllocEventID<HardEvent::MTE1_M>();
    mte1ToMA[1] = pipe_.AllocEventID<HardEvent::MTE1_M>();
    mte1ToMB[0] = pipe_.AllocEventID<HardEvent::MTE1_M>();
    mte1ToMB[1] = pipe_.AllocEventID<HardEvent::MTE1_M>();
    SetFlag<HardEvent::M_MTE1>(mToMte1A[0]);
    SetFlag<HardEvent::M_MTE1>(mToMte1A[1]);
    SetFlag<HardEvent::M_MTE1>(mToMte1B[0]);
    SetFlag<HardEvent::M_MTE1>(mToMte1B[1]);
    aL0Tensor_ = aBufL0_.Get<float>();
    bL0Tensor_ = bBufL0_.Get<float>();

    // L0C
    pipe_.InitBuffer(cBufL0_, L0C_SIZE);
    fixToM[0] = pipe_.AllocEventID<HardEvent::FIX_M>();
    fixToM[1] = pipe_.AllocEventID<HardEvent::FIX_M>();
    mToFix[0] = pipe_.AllocEventID<HardEvent::M_FIX>();
    mToFix[1] = pipe_.AllocEventID<HardEvent::M_FIX>();
    SetFlag<HardEvent::FIX_M>(fixToM[0]);
    SetFlag<HardEvent::FIX_M>(fixToM[1]);
    cL0Tensor_ = cBufL0_.Get<float>();
}

__aicore__ inline void Kernel::Init(
        __gm__ uint8_t *initialState,
        __gm__ uint8_t *kgexp,
        __gm__ uint8_t *value,
        __gm__ uint8_t *kCumdecay,
        __gm__ uint8_t *qgexp,
        __gm__ uint8_t *gexp,
        __gm__ uint8_t *actualSeqlens,
        __gm__ uint8_t *attnInterOut,
        __gm__ uint8_t *vNewOut,
        __gm__ uint8_t *workspace,
        const TilingData *__restrict tilingData)
{
    PipeBarrier<PIPE_ALL>();
    blockIdx_ = GetBlockIdx();
    blockNum_ = GetBlockNum();
    params_ = tilingData;
    initialStateGm_.SetGlobalBuffer((__gm__ float*)initialState);
    kgexpGm_.SetGlobalBuffer((__gm__ float*)kgexp);
    valueGm_.SetGlobalBuffer((__gm__ float*)value);
    kCumdecayGm_.SetGlobalBuffer((__gm__ float*)kCumdecay);
    qgexpGm_.SetGlobalBuffer((__gm__ float*)qgexp);
    gexpGm_.SetGlobalBuffer((__gm__ float*)gexp);
    actualSeqlensGm_.SetGlobalBuffer((__gm__ int32_t*)actualSeqlens);
    attnInterOutGm_.SetGlobalBuffer((__gm__ float*)attnInterOut);
    vNewOutGm_.SetGlobalBuffer((__gm__ float*)vNewOut);
    if ASCEND_IS_AIV {
        VectorBufferInit();
    } else {
        CubeBufferInit();
    }
}

template <bool enTranspose = false>
__aicore__ inline void Kernel::LoadDataToL0A(const LocalTensor<float>& aL0Tensor, const LocalTensor<float>& aL1Tensor,
    uint32_t fullSize, uint32_t kSplitSize, uint32_t mSplitSize)
{
    if constexpr (enTranspose) {
        // 对于 v_new_out.trans @ kgexp
        // v_new_out 的L1排布是 ZZ，而 v_new_out.trans 的排布是 NN，A矩阵的要求的排步是 ZZ，因此需要分型的转置
        LoadData2dTransposeParams loadData2dTransposeParams;
        loadData2dTransposeParams.startIndex = 0;
        loadData2dTransposeParams.srcStride = fullSize / fractionH;
        loadData2dTransposeParams.dstFracGap = 0;
        loadData2dTransposeParams.dstGap = 1;
        loadData2dTransposeParams.repeatTimes = kSplitSize / fractionH;
        uint32_t loopTimes = mSplitSize / fractionH;
        uint64_t l1Offset = fractionH * fractionH;
        uint64_t l0Offset = kSplitSize * fractionH;
        // 按行迭代
        for(uint32_t i = 0; i < loopTimes; i++) {
            LoadDataWithTranspose(aL0Tensor[i * l0Offset], aL1Tensor[i * l1Offset], loadData2dTransposeParams);
        }
    } else {
        // 对于 qgexp @ state.trans
        // qgexp 的排布是 ZZ，A矩阵的要求的排步是 ZZ，因此需要不需要分型的转置
        LoadData2DParams loadData2DParams;
        loadData2DParams.startIndex = 0;
        loadData2DParams.srcStride = 1;
        loadData2DParams.dstGap = 0;
        loadData2DParams.repeatTimes = (mSplitSize / fractionH) * (kSplitSize / fractionW);
        loadData2DParams.ifTranspose = false;
        LoadData(aL0Tensor, aL1Tensor, loadData2DParams);
    }
}

template <bool enTranspose = false>
__aicore__ inline void Kernel::LoadDataToL0B(const LocalTensor<float>& bL0Tensor, const LocalTensor<float>& bL1Tensor,
    uint32_t fullSize, uint32_t kSplitSize, uint32_t nSplitSize)
{
    if constexpr (enTranspose) {
        // 对于 qgexp @ state.trans
        // state 的排布是 NZ，而 state.trans 的排布是 ZN，B矩阵的要求是ZN，不需要转置，直接最简单拷贝就行
        LoadData2DParams loadData2DParams;
        loadData2DParams.startIndex = 0;
        loadData2DParams.srcStride = 1;
        loadData2DParams.dstGap = 0;
        loadData2DParams.ifTranspose = false;
        if(fullSize == nSplitSize) { // 直接完整拷贝即可
            loadData2DParams.repeatTimes = ((nSplitSize + fractionH - 1) / fractionH) * (kSplitSize / fractionW);
            LoadData(bL0Tensor, bL1Tensor, loadData2DParams);
        } else { // 需要处理截断
            loadData2DParams.repeatTimes = (nSplitSize + fractionH - 1) / fractionH;
            uint32_t loopTimes = kSplitSize / fractionW;
            uint64_t l1Offset = fullSize * fractionW;
            uint64_t l0Offset = nSplitSize * fractionW;
            for (uint32_t i = 0; i < loopTimes; i++) {
                LoadData(bL0Tensor[i * l0Offset], bL1Tensor[i * l1Offset], loadData2DParams);
            }
        }
    } else {
        // 对于 v_new_out.trans @ kgexp
        // kgexp 的排布是 ZZ，B矩阵的要求的排步是 ZN，因此需要需要分型做转置
        LoadData2dTransposeParams loadData2dTransposeParams;
        loadData2dTransposeParams.startIndex = 0;
        loadData2dTransposeParams.srcStride = fullSize / fractionH;
        loadData2dTransposeParams.dstFracGap = nSplitSize / fractionH - 1;
        loadData2dTransposeParams.dstGap = 2 * nSplitSize / fractionH - 1;
        loadData2dTransposeParams.repeatTimes = kSplitSize / fractionH;
        // 按照列迭代
        uint32_t loopTimes = nSplitSize / fractionH;
        uint64_t l1Offset = fractionH * fractionH;
        uint64_t l0Offset = fractionH * fractionH;
        for(uint32_t i = 0; i < loopTimes; i++) {
            LoadDataWithTranspose(bL0Tensor[i * l0Offset], bL1Tensor[i * l1Offset], loadData2dTransposeParams);
        }
    }
}

// L1->L0A 切 M (转置的场景，入参中k与m需要互换)
template <bool enTranspose = false>
__aicore__ inline int32_t Kernel::LoadDataL0A(const LocalTensor<float>& aL1Tensor,
    uint32_t fullSize, uint32_t kSplitSize, uint32_t mSplitSize)
{
    int32_t aL0CurIter = cubeL0AIter;
    size_t aL0Offset = (aL0CurIter & 1) * (L0A_PP_SIZE >> 2);
    WaitFlag<HardEvent::M_MTE1>(mToMte1A[aL0CurIter & 1]);
    LoadDataToL0A<enTranspose>(aL0Tensor_[aL0Offset], aL1Tensor, fullSize, kSplitSize, mSplitSize);
    SetFlag<HardEvent::MTE1_M>(mte1ToMA[aL0CurIter & 1]);
    cubeL0AIter++;
    return aL0CurIter;
}

// L1→L0B + 切N (转置的场景，入参中n与k需要互换)
template <bool enTranspose = false>
__aicore__ inline int32_t Kernel::LoadDataL0B(const LocalTensor<float>& bL1Tensor,
    uint32_t fullSize, uint32_t kSplitSize, uint32_t nSplitSize)
{
    int32_t bL0CurIter = cubeL0BIter;
    uint32_t bL0Offset = (bL0CurIter & 1) * (L0B_PP_SIZE >> 2);
    WaitFlag<HardEvent::M_MTE1>(mToMte1B[bL0CurIter & 1]);
    LoadDataToL0B<enTranspose>(bL0Tensor_[bL0Offset], bL1Tensor, fullSize, kSplitSize, nSplitSize);
    SetFlag<HardEvent::MTE1_M>(mte1ToMB[bL0CurIter & 1]);
    cubeL0BIter++;
    return bL0CurIter;
}

template<bool enableZZ=true>
__aicore__ inline void Kernel::LoadDataToL1(const LocalTensor<float>& l1Tensor,
    const GlobalTensor<float>& gmTensor, uint32_t m, uint32_t n)
{
    if constexpr (enableZZ) {
        // 相当于多次执行ND->NZ，达到ZZ的效果
        Nd2NzParams nd2nzPara;
        nd2nzPara.ndNum = m / fractionH;
        nd2nzPara.nValue = fractionH;
        nd2nzPara.dValue = n;
        nd2nzPara.srcDValue = n;
        nd2nzPara.dstNzC0Stride = fractionH;
        nd2nzPara.dstNzNStride = 1;
        nd2nzPara.srcNdMatrixStride = fractionH * n;
        nd2nzPara.dstNzMatrixStride = fractionH * n;
        DataCopy(l1Tensor, gmTensor, nd2nzPara);
    } else {
        Nd2NzParams nd2nzPara;
        nd2nzPara.ndNum = 1;
        nd2nzPara.nValue = m;
        nd2nzPara.dValue = n;
        nd2nzPara.srcDValue = n;
        nd2nzPara.dstNzC0Stride = m;
        nd2nzPara.dstNzNStride = 1;
        nd2nzPara.srcNdMatrixStride = 0;
        nd2nzPara.dstNzMatrixStride = 0;
        DataCopy(l1Tensor, gmTensor, nd2nzPara);
    }
}

template<bool enableZZ = true, bool splitM = false>
__aicore__ inline int32_t Kernel::LoadL1A(const GlobalTensor<float> &gm, uint32_t m, uint32_t k,
    uint32_t mStart, uint32_t mEnd)
{
    int32_t curL1Iter = cubeL1AIter;
    size_t l1Offset = (curL1Iter & 1) * (L1A_PP_SIZE >> 2);
    WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[curL1Iter & 1]);
    // A 转置或者不转置得场景，ZZ排布都有优势
    if constexpr (splitM) {
        LoadDataToL1<enableZZ>(aL1Tensor_[l1Offset + mStart * k], gm[mStart * k], mEnd - mStart, k);
    } else {
        LoadDataToL1<enableZZ>(aL1Tensor_[l1Offset], gm, m, k);
    }
    SetFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[curL1Iter & 1]);
    cubeL1AIter++;
    return curL1Iter;
}

template<bool enableZZ = true>
__aicore__ inline int32_t Kernel::LoadL1B(const GlobalTensor<float> &gm, uint32_t k, uint32_t n)
{
    int32_t curL1Iter = cubeL1BIter;
    size_t l1Offset = (curL1Iter & 1) * (L1B_PP_SIZE >> 2);
    // int32_t l1Flag = B_EVENT0 + (curL1Iter & 1);
    WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[curL1Iter & 1]);
    LoadDataToL1<enableZZ>(bL1Tensor_[l1Offset], gm, k, n);
    SetFlag<HardEvent::MTE2_MTE1>(mte2ToMte1B[curL1Iter & 1]);
    cubeL1BIter++;
    return curL1Iter;
}

template <bool enBTranspose = true>
__aicore__ inline void Kernel::MatmulIterN(const LocalTensor<float> &cL0,
    const LocalTensor<float> &aL0, const LocalTensor<float> &bL1, uint32_t m, uint32_t k, uint32_t n)
{
    uint32_t nLoop = n / baseN;
    MmadParams mmadParams;
    mmadParams.m = m;
    mmadParams.n = baseN;
    mmadParams.k = k;
    mmadParams.unitFlag = 0;
    mmadParams.cmatrixInitVal = true;
    for (uint32_t nIter = 0; nIter < nLoop; nIter++) { // 切核场景，需要进行修改
        // 载入 L0B
        int32_t l0BCurIter = 0;
        if constexpr (enBTranspose) {
            // NZ -> ZN
            l0BCurIter = LoadDataL0B<true>(bL1[nIter * fractionW * baseN], n, k, baseN);
        } else {
            // ZZ -> ZN
            l0BCurIter = LoadDataL0B<false>(bL1[nIter * fractionH * baseN], n, k, baseN);
        }
        size_t bL0Offset = (l0BCurIter & 1) * (L0B_PP_SIZE >> 2);
        // 计算 mmad
        WaitFlag<HardEvent::MTE1_M>(mte1ToMB[l0BCurIter & 1]);
        Mmad(cL0[nIter * m * baseN], aL0, bL0Tensor_[bL0Offset], mmadParams);
        SetFlag<HardEvent::M_MTE1>(mToMte1B[l0BCurIter & 1]);
    }
}

template<bool enATranspose = false, bool enBTranspose = true, bool enAtomicAdd = false>
__aicore__ inline void Kernel::MatmulSplitM(const GlobalTensor<float> &out, const LocalTensor<float> &aL1,
    const LocalTensor<float> &bL1, uint32_t m, uint32_t k, uint32_t n, uint32_t mStart, uint32_t mEnd)
{
    FixpipeParamsV220 fixParams;
    fixParams.nSize = n;
    fixParams.mSize = baseM;
    fixParams.srcStride = baseM;
    fixParams.dstStride = n;
    fixParams.ndNum = 1;
    fixParams.unitFlag = 0;
    mStart /= baseM;
    mEnd /= baseM;
    for (uint32_t i = mStart; i < mEnd; i++) {
        // L1(ZZ/NN) -> L0A(ZZ), 因此需要 i * baseM * fractionW 的偏移量
        int32_t l0ACurIter = 0;
        if constexpr (enATranspose) {
            // NN->ZZ
            l0ACurIter = LoadDataL0A<true>(aL1[i * baseM * fractionH], m, k, baseM);
        } else {
            // ZZ->ZZ
            l0ACurIter = LoadDataL0A<false>(aL1[i * baseM * k], m, k, baseM);
        }
        size_t aL0Offset = (l0ACurIter & 1) * (L0A_PP_SIZE >> 2);
        size_t cL0Offset = (cubeL0CIter & 1) * (L0C_PP_SIZE >> 2);
        // 切核此处要变 bL1 偏移量
        WaitFlag<HardEvent::FIX_M>(fixToM[cubeL0CIter & 1]);
        WaitFlag<HardEvent::MTE1_M>(mte1ToMA[l0ACurIter & 1]);
        MatmulIterN<enBTranspose>(cL0Tensor_[cL0Offset], aL0Tensor_[aL0Offset], bL1, baseM, k, n);
        SetFlag<HardEvent::M_MTE1>(mToMte1A[l0ACurIter & 1]);
        SetFlag<HardEvent::M_FIX>(mToFix[cubeL0CIter & 1]);
        // 矩阵乘法计算完成，允许fix_pipe开始搬运
        WaitFlag<HardEvent::M_FIX>(mToFix[cubeL0CIter & 1]);
        // 搬运到 GM（或者 atomic_add)
        if constexpr (enAtomicAdd) {
            SetAtomicAdd<float>();
        }
        Fixpipe(out[i * baseM * n], cL0Tensor_[cL0Offset], fixParams); // 切核此处要变out偏移量
        if constexpr (enAtomicAdd) {
            SetAtomicNone();
        }
        // fix_pipe搬运完成，允许矩阵乘法
        SetFlag<HardEvent::FIX_M>(fixToM[cubeL0CIter & 1]);
        cubeL0CIter++;
    }
}

template<bool splitM = false>
__aicore__ inline void Kernel::GetMRange(uint32_t &mStart, uint32_t &mEnd, uint32_t mLength)
{
    if constexpr (splitM) {
        mStart = (blockIdx_ % params_->mSplitNum) * (mLength / params_->mSplitNum);
        mEnd = mStart + (mLength / params_->mSplitNum);
    } else {
        mStart = 0;
        mEnd = mLength;
    }
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleChunkCubeProcessC0(const GlobalTensor<float> &state,
    const GlobalTensor<float> &kCumdecay)
{
    // 载入 kCumdecay (ZZ) 到 L1A
    uint32_t mStart = 0;
    uint32_t mEnd = 0;
    GetMRange<splitM>(mStart, mEnd, params_->chunkSize);
    kCumdecayIter = LoadL1A<true, splitM>(kCumdecay, params_->chunkSize, params_->kDim, mStart, mEnd);
    // 等待上一轮 state 更新完毕，才能拷贝 state（切分场景需要全核同步）
    if constexpr (splitM) {
        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C0V0);
    } else {
        WaitFlag<HardEvent::FIX_MTE2>(fixToMte2);
    }
    // 载入 state (NZ)
    stateIter = LoadL1B<false>(state, params_->vDim, params_->kDim);
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleChunkCubeProcessC1(const GlobalTensor<float> &vNewOut,
    const GlobalTensor<float> &qgexp, const GlobalTensor<float> &kgexp)
{
    // 载入  qgexp (ZZ) 到 L1A
    uint32_t mStart = 0;
    uint32_t mEnd = 0;
    GetMRange<splitM>(mStart, mEnd, params_->chunkSize);
    qgexpIter = LoadL1A<true, splitM>(qgexp, params_->chunkSize, params_->kDim, mStart, mEnd);
    // 载入 kgexp (ZZ) 到 L1B
    kgexpIter = LoadL1B(kgexp, params_->chunkSize, params_->kDim);
    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1B[stateIter & 1]);
    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[kCumdecayIter & 1]);
    // 计算 vNewOut = kCumdecay @ state.trans
    MatmulSplitM(vNewOut, aL1Tensor_[(kCumdecayIter & 1) * (L1A_PP_SIZE >> 2)],
        bL1Tensor_[(stateIter & 1) * (L1B_PP_SIZE >> 2)],
        params_->chunkSize, params_->kDim, params_->vDim, mStart, mEnd);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[kCumdecayIter & 1]);
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleChunkCubeProcessC2(const GlobalTensor<float> &attnInterOut)
{
    // 计算 attnIterOut = qgexp @ state.trans
    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[qgexpIter & 1]);
    uint32_t mStart = 0;
    uint32_t mEnd = 0;
    GetMRange<splitM>(mStart, mEnd, params_->chunkSize);
    MatmulSplitM(attnInterOut, aL1Tensor_[(qgexpIter & 1) * (L1A_PP_SIZE >> 2)],
        bL1Tensor_[(stateIter & 1) * (L1B_PP_SIZE >> 2)],
        params_->chunkSize, params_->kDim, params_->vDim, mStart, mEnd);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[qgexpIter & 1]);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[stateIter & 1]);
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleChunkCubeProcessC3(const GlobalTensor<float> &state,
    const GlobalTensor<float> &vNewOut)
{
    // 全载 vNewOut GM -> L1A -> L0A（L1B 已经载入 kgexp）
    vNewOutIter = LoadL1A<true, false>(vNewOut, params_->chunkSize, params_->vDim, 0, params_->chunkSize);
    // 计算 initial_state += v_new_out.trans @ state（A转置+B不转置+AtomicAdd）
    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1B[kgexpIter & 1]);
    WaitFlag<HardEvent::MTE2_MTE1>(mte2ToMte1A[vNewOutIter & 1]);
    uint32_t mStart = 0;
    uint32_t mEnd = 0;
    GetMRange<splitM>(mStart, mEnd, params_->vDim);
    MatmulSplitM<true, false, true>(state, aL1Tensor_[(vNewOutIter & 1) * (L1A_PP_SIZE >> 2)],
        bL1Tensor_[(kgexpIter & 1) * (L1B_PP_SIZE >> 2)],
        params_->vDim, params_->chunkSize, params_->kDim, mStart, mEnd);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[vNewOutIter & 1]);
    SetFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[kgexpIter & 1]);
    if constexpr (splitM) {
        // 切 M 场景需要做全核同步
        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_FIX>(SYNC_FLAG_C0V0);
    } else {
        // 不切 M 的话只需要单核同步即可
        SetFlag<HardEvent::FIX_MTE2>(fixToMte2);
    }
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleChunkCubeProcess(
    const GlobalTensor<float> &state, const GlobalTensor<float> &attnInterOut, const GlobalTensor<float> &vNewOut,
    const GlobalTensor<float> &kgexp, const GlobalTensor<float> &kCumdecay, const GlobalTensor<float> &qgexp)
{
    SingleChunkCubeProcessC0<splitM>(state, kCumdecay);
    // C0 拷贝完，向 V0 同步
    CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C0V0);
    SingleChunkCubeProcessC1<splitM>(vNewOut, qgexp, kgexp);
    // C1 结束向 V1 同步
    CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_FIX>(SYNC_FLAG_C1V1);
    SingleChunkCubeProcessC2<splitM>(attnInterOut);
    // C3 等待 V1 (等待 vNewOut ready)
    CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_V1C3);
    SingleChunkCubeProcessC3<splitM>(state, vNewOut);
}

__aicore__ inline void Kernel::SingleChunkVecProcessV0(const GlobalTensor<float> &state,
    float gexp, size_t size)
{
    constexpr size_t baseSize = 1024; // 4 KB，当前较好的拷贝大小
    size_t iterCount = size / baseSize;
    for (size_t i = 0; i < iterCount; i++) {
        size_t v0Offset = (vec0Iter & 1) * (UB_STATE_PP_SIZE >> 2);
        // CopyIn
        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[vec0Iter & 1]);
        DataCopy(stateTensor_[v0Offset], state[i * baseSize], baseSize);
        SetFlag<HardEvent::MTE2_V>(mte2ToVV0[vec0Iter & 1]);
        // Compute
        WaitFlag<HardEvent::MTE2_V>(mte2ToVV0[vec0Iter & 1]);
        Muls(stateTensor_[v0Offset], stateTensor_[v0Offset], gexp, baseSize);
        SetFlag<HardEvent::V_MTE3>(vToMte3V0[vec0Iter & 1]);
        // CopyOut
        WaitFlag<HardEvent::V_MTE3>(vToMte3V0[vec0Iter & 1]);
        DataCopy(state[i * baseSize], stateTensor_[v0Offset], baseSize);
        SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[vec0Iter & 1]);
        vec0Iter++;
    }
}

__aicore__ inline void Kernel::SingleChunkVecProcessV1(const GlobalTensor<float> &vNewOut,
    const GlobalTensor<float> &value, size_t size)
{
    constexpr size_t baseSize = 1024; // 4 KB，暂定拷贝大小
    size_t iterCount = size / baseSize;
    for (size_t i = 0; i < iterCount; i++) {
        size_t v1Offset = (vec1Iter & 1) * (UB_STATE_PP_SIZE >> 2);
        // CopyIn
        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[vec1Iter & 1]);
        DataCopy(valueTensor_[v1Offset], value[i * baseSize], baseSize);
        DataCopy(vNewOutTensor_[v1Offset], vNewOut[i * baseSize], baseSize);
        SetFlag<HardEvent::MTE2_V>(mte2ToVV1[vec1Iter & 1]);
        // Compute
        WaitFlag<HardEvent::MTE2_V>(mte2ToVV1[vec1Iter & 1]);
        Sub(valueTensor_[v1Offset], valueTensor_[v1Offset], vNewOutTensor_[v1Offset], baseSize);
        SetFlag<HardEvent::V_MTE3>(vToMte3V1[vec1Iter & 1]);
        // CopyOut
        WaitFlag<HardEvent::V_MTE3>(vToMte3V1[vec1Iter & 1]);
        DataCopy(vNewOut[i * baseSize], valueTensor_[v1Offset], baseSize);
        SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[vec1Iter & 1]);
        vec1Iter++;
    }
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleChunkVecProcess(
    const GlobalTensor<float> &state, const GlobalTensor<float> &vNewOut, const GlobalTensor<float> &value, float gexp)
{
    // V0 需要同步 C0
    uint32_t sOffset = 0;
    uint32_t sLength = params_->kDim * params_->vDim;
    if constexpr (splitM) {
        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C0V0);
        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C0V0);
        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C0V0);
        sLength /= params_->mSplitNum;
        sOffset = sLength * (blockIdx_ % params_->mSplitNum);
    } else {
        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C0V0);
    }
    SingleChunkVecProcessV0(state[sOffset], gexp, sLength);
    // V1 需要同步 C1
    uint32_t vOffset = 0;
    uint32_t vLength = params_->chunkSize * params_->vDim;
    if constexpr (splitM) {
        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C1V1);
        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C1V1);
        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE2>(SYNC_FLAG_C1V1);
        vLength /= params_->mSplitNum;
        vOffset = vLength * (blockIdx_ % params_->mSplitNum);
    } else {
        CrossCoreWaitFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE2>(SYNC_FLAG_C1V1);
    }
    SingleChunkVecProcessV1(vNewOut[vOffset], value[vOffset], vLength);
    // V1 结束，需要同步 C3
    if constexpr (splitM) {
        CrossCoreSetFlag<SYNC_MODE_ALL, PIPE_MTE3>(SYNC_FLAG_V1C3);
        CrossCoreWaitFlag<SYNC_MODE_ALL, PIPE_MTE3>(SYNC_FLAG_V1C3);
        CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE3>(SYNC_FLAG_V1C3);
    } else {
        CrossCoreSetFlag<SYNC_MODE_CUBE_VEC, PIPE_MTE3>(SYNC_FLAG_V1C3);
    }
}

template<bool splitM = false>
__aicore__ inline void Kernel::SingleBatchProcess(
    uint32_t curBatch, uint32_t curHead, uint64_t seqStartChunk, uint64_t seqEndChunk)
{
    if constexpr (splitM) {
        // head+msplit核间并行
        if (curHead % (blockNum_ / params_->mSplitNum) != (blockIdx_ / params_->mSplitNum)) {
            return;
        }
    } else {
        // batch+head核间并行
        if ((curBatch * params_->headNum + curHead) % blockNum_ != blockIdx_) {
            return;
        }
    }
    size_t chunkOffset = curHead * params_->chunkNum + seqStartChunk;
    // [b, hv, dk, dv]
    size_t sOffset = (curBatch * params_->headNum + curHead) * params_->kDim * params_->vDim;
    // [hv, n_chunk, chunk_size, dk]
    size_t kOffset = chunkOffset * params_->chunkSize * params_->kDim;
    // [hv, n_chunk, chunk_size, dv]
    size_t vOffset = chunkOffset * params_->chunkSize * params_->vDim;
    // [hv, n_chunk, chunk_size, 1] 取最后一个值
    size_t gOffset = (chunkOffset + 1) * params_->chunkSize - 1;
    for (uint64_t i = seqStartChunk; i < seqEndChunk; i++) {
        if ASCEND_IS_AIV {
            // [hv, n_chunk, chunk_size, 1] 最后一个
            float gexp = gexpGm_.GetValue(gOffset);
            SingleChunkVecProcess<splitM>(initialStateGm_[sOffset], vNewOutGm_[vOffset], valueGm_[vOffset], gexp);
        } else {
            SingleChunkCubeProcess<splitM>(initialStateGm_[sOffset], attnInterOutGm_[vOffset], vNewOutGm_[vOffset],
                kgexpGm_[kOffset], kCumdecayGm_[kOffset], qgexpGm_[kOffset]);
        }
        kOffset += params_->chunkSize * params_->kDim;
        vOffset += params_->chunkSize * params_->vDim;
        gOffset += params_->chunkSize;
    }
}

template<bool splitM = false>
__aicore__ inline void Kernel::RunProcess()
{
    int32_t seqStartChunk = 0;
    for (uint32_t curBatch = 0; curBatch  < params_->batchNum; curBatch++) {
        int32_t seqLen = actualSeqlensGm_.GetValue((size_t)curBatch);
        if (unlikely(seqLen < 0)) {
            assert(false, "elements in actual_seqlens must be >= 0!\n");
            Trap();
            return;
        }
        if (unlikely(seqLen % params_->chunkSize != 0)) {
            assert(false, "elements in actual_seqlens must be divied by chunk_size!\n");
            Trap();
            return;
        }
        int32_t seqEndChunk = seqStartChunk + seqLen / params_->chunkSize;
        if (seqEndChunk > params_->chunkNum) {
            assert(false, "sum of actual_seqlens must equals to n_chunks!\n");
            Trap();
            return;
        }
        for (uint32_t curHead = 0; curHead < params_->headNum; curHead++) {
            SingleBatchProcess<splitM>(curBatch, curHead, seqStartChunk, seqEndChunk);
        }
        seqStartChunk = seqEndChunk;
    }
}

__aicore__ inline void Kernel::Process()
{
    if (params_->enableMSplit) {
        RunProcess<true>();
    } else {
        RunProcess<false>();
    }
    if ASCEND_IS_AIC {
        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[0]);
        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2A[1]);
        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[0]);
        WaitFlag<HardEvent::MTE1_MTE2>(mte1ToMte2B[1]);

        WaitFlag<HardEvent::M_MTE1>(mToMte1A[0]);
        WaitFlag<HardEvent::M_MTE1>(mToMte1A[1]);
        WaitFlag<HardEvent::M_MTE1>(mToMte1B[0]);
        WaitFlag<HardEvent::M_MTE1>(mToMte1B[1]);

        WaitFlag<HardEvent::FIX_M>(fixToM[0]);
        WaitFlag<HardEvent::FIX_M>(fixToM[1]);

        WaitFlag<HardEvent::FIX_MTE2>(fixToMte2);
    } else {
        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[0]);
        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V0[1]);
        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[0]);
        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2V1[1]);
    }
    PipeBarrier<PIPE_ALL>();
}

}

