/*!
 * \file ai_infra_fused_causal_conv1d.cpp
 * \brief
 */

#include "ai_infra_fused_causal_conv1d_fn_cutbs.h"
#include "ai_infra_fused_causal_conv1d_fn_cutbsd.h"
#include "ai_infra_fused_causal_conv1d_update.h"

using namespace AscendC;
using namespace AiInfraFusedCausalConv1d;

#define TILING_KEY_FN_CUTBSD 0
#define TILING_KEY_FN_CUTBS 1
#define TILING_KEY_UPDATE_X_BSH 2
#define TILING_KEY_UPDATE_X_TND 3

extern "C" __global__ __aicore__ void ai_infra_fused_causal_conv1d(GM_ADDR x, GM_ADDR weight, GM_ADDR conv_states,
    GM_ADDR query_start_loc, GM_ADDR cache_indices, GM_ADDR initial_state_mode, GM_ADDR bias,
    GM_ADDR num_accepted_tokens, GM_ADDR num_computed_tokens, GM_ADDR block_idx_first_scheduled_token,
    GM_ADDR block_idx_last_scheduled_token, GM_ADDR initial_state_idx, GM_ADDR conv_states_out, GM_ADDR output,
    GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA_WITH_STRUCT(AiInfraFusedCausalConv1dTilingData, tilingDataIn, tiling);
    const AiInfraFusedCausalConv1dTilingData *__restrict tilingData = &tilingDataIn;
    TPipe pipe;

    if (TILING_KEY_IS(TILING_KEY_FN_CUTBSD)) {
        KERNEL_TASK_TYPE(TILING_KEY_FN_CUTBSD, KERNEL_TYPE_MIX_AIV_1_0);
#if (ORIG_DTYPE_X == DT_FLOAT16)
        KernelAiInfraFusedCausalConv1dFnCutbsd<half> opFn(&pipe, tilingData);
#endif
#if (ORIG_DTYPE_X == DT_BF16)
        KernelAiInfraFusedCausalConv1dFnCutbsd<bfloat16_t> opFn(&pipe, tilingData);
#endif
        opFn.Init(x,
            weight,
            conv_states,
            query_start_loc,
            cache_indices,
            num_accepted_tokens,
            num_computed_tokens,
            block_idx_first_scheduled_token,
            block_idx_last_scheduled_token,
            initial_state_idx,
            output);
        opFn.Process();
    } else if (TILING_KEY_IS(TILING_KEY_FN_CUTBS)) {
        KERNEL_TASK_TYPE(TILING_KEY_FN_CUTBS, KERNEL_TYPE_MIX_AIV_1_0);
#if (ORIG_DTYPE_X == DT_FLOAT16)
        KernelAiInfraFusedCausalConv1dFnCutbs<half> opFn(&pipe, tilingData);
#endif
#if (ORIG_DTYPE_X == DT_BF16)
        KernelAiInfraFusedCausalConv1dFnCutbs<bfloat16_t> opFn(&pipe, tilingData);
#endif
        opFn.Init(x,
            weight,
            conv_states,
            query_start_loc,
            cache_indices,
            num_accepted_tokens,
            num_computed_tokens,
            block_idx_first_scheduled_token,
            block_idx_last_scheduled_token,
            initial_state_idx,
            output);
        opFn.Process();
    } else if (TILING_KEY_IS(TILING_KEY_UPDATE_X_BSH)) {
        KERNEL_TASK_TYPE(TILING_KEY_UPDATE_X_BSH, KERNEL_TYPE_AIV_ONLY);
#if (ORIG_DTYPE_X == DT_FLOAT16)
        KernelAiInfraFusedCausalConv1dUpdate<half> opUpdate(&pipe, tilingData);
#endif
#if (ORIG_DTYPE_X == DT_BF16)
        KernelAiInfraFusedCausalConv1dUpdate<bfloat16_t> opUpdate(&pipe, tilingData);
#endif
        opUpdate.Init(x,
            weight,
            conv_states,
            query_start_loc,
            cache_indices,
            num_accepted_tokens,
            num_computed_tokens,
            block_idx_first_scheduled_token,
            block_idx_last_scheduled_token,
            initial_state_idx,
            output);
        opUpdate.Process();
    }
}

