32	std::string ConvertContainerToString(const C &container, const size_t size)
33	{
34	    std::stringstream ss;
35	    ss << "[";
36	    bool isFirst = true;
37	    for (size_t i = 0; i < size; i++) {
38	        if (!isFirst) {
39	            ss << ", ";
40	        }
