48	class ChunkGatedDeltaRuleRecurrenceTilingCheck {
49	public:
50	    ChunkGatedDeltaRuleRecurrenceTilingCheck(
51	        const ChunkGatedDeltaRuleRecurrenceParaInfo &paraInfo,
52	        const ChunkGatedDeltaRuleRecurrenceShapeInfo &shapeInfo)
53	        : paraInfo_(paraInfo), shapeInfo_(shapeInfo) {}
54	
55	    ge::graphStatus CheckParaInfo() const
56	    {
57	        if (!CheckInitialStateOut() || !CheckKgexp() || !CheckValue() ||
58	            !CheckKCumdecay() || !CheckQgexp() || !CheckGexp() || !CheckActualSeqlens()) {
59	            return ge::GRAPH_FAILED;
60	        }
61	        return ge::GRAPH_SUCCESS;
62	    }
63	
64	    ge::graphStatus CheckShapeInfo() const
65	    {
66	        if (shapeInfo_.batchNum > MAX_B_SIZE) {
67	            OPS_LOG_E(paraInfo_.opName, "batchNum should not be greater than %u, got %u.",
68	                MAX_B_SIZE, shapeInfo_.batchNum);
69	            return ge::GRAPH_FAILED;
70	        }
71	        if (shapeInfo_.headNum > MAX_HV_SIZE) {
72	            OPS_LOG_E(paraInfo_.opName, "hvsize should not be greater than %u, got %u.",
73	                MAX_HV_SIZE, shapeInfo_.headNum);
74	            return ge::GRAPH_FAILED;
75	        }
76	
77	        if (shapeInfo_.kDim != VALID_KDIM) {
78	            OPS_LOG_E(paraInfo_.opName, "dksize should be %u, got %u.", VALID_KDIM, shapeInfo_.kDim);
79	            return ge::GRAPH_FAILED;
80	        }
81	
82	        if (shapeInfo_.vDim != VALID_VDIM) {
83	            OPS_LOG_E(paraInfo_.opName, "dvsize should be %u, got %u.", VALID_VDIM, shapeInfo_.headNum);
84	            return ge::GRAPH_FAILED;
85	        }
86	
87	        const std::set<uint32_t> vaildChunkSize {32, 64, 128, 256};
88	        if (vaildChunkSize.find(shapeInfo_.chunkSize) == vaildChunkSize.end()) {
89	            OPS_LOG_E(paraInfo_.opName, "chunksize should not be of {32, 64, 128, 256}, got %u.",
90	                shapeInfo_.headNum);
91	            return ge::GRAPH_FAILED;
92	        }
93	
94	        return ge::GRAPH_SUCCESS;
95	    }
96	
97	private:
98	    static constexpr uint32_t MAX_B_SIZE = 65536U;
99	    static constexpr uint32_t MAX_HV_SIZE = 128U;
100	    static constexpr uint32_t VALID_KDIM = 128U;
101	    static constexpr uint32_t VALID_VDIM = 128U;
102	    static constexpr uint32_t N_CHUNKS_SIZE = 1;
103	
104	    bool IsSingleParamValid(const RequiredParaInfo &param, const char *paramName,
105	        const ge::DataType expectedDtype, const ge::Format expectedFormat,
106	        const std::vector<size_t> &expectedDim) const
107	    {
108	        if((param.shape == nullptr) || (param.desc == nullptr)) {
109	            OPS_LOG_E(paraInfo_.opName, "%s should not be null.", paramName);
110	            return false;
111	        }
112	
113	        ge::DataType dtype = param.desc->GetDataType();
114	        if (dtype != expectedDtype) {
115	            OPS_LOG_E(paraInfo_.opName, "%s datatype only supports %s, but got %s.", paramName,
116	                TypeUtils::DataTypeToSerialString(expectedDtype).c_str(),
117	                TypeUtils::DataTypeToSerialString(dtype).c_str());
118	            return false;
119	        }
120	
121	        size_t dimNum = param.shape->GetStorageShape().GetDimNum();
122	        if (dimNum != expectedDim.size()) {
123	            OPS_LOG_E(paraInfo_.opName, "%s dim num supports only %zu, but got %zu.", paramName,
124	                expectedDim.size(), dimNum);
125	            return false;
126	        }
127	
128	        for (size_t i = 0; i < dimNum; i++) {
129	            size_t dim = param.shape->GetStorageShape().GetDim(i);
130	            if (dim != expectedDim[i]) {
131	                OPS_LOG_E(paraInfo_.opName, "%s dim supports only %s, but got %s.", paramName,
132	                    ConvertContainerToString(expectedDim, expectedDim.size()).c_str(),
133	                    ConvertContainerToString(param.shape->GetStorageShape(), dimNum).c_str());
134	                return false;
135	            }
136	        }
137	        return true;
138	    }
139	
140	    bool CheckInitialStateOut() const
141	    {
142	        return IsSingleParamValid(paraInfo_.initialStateOut, "initial_state_out", ge::DT_FLOAT, ge::FORMAT_ND,
143	            {shapeInfo_.batchNum, shapeInfo_.headNum, shapeInfo_.vDim, shapeInfo_.kDim});
144	    }
145	
146	    bool CheckKgexp() const
147	    {
148	        return IsSingleParamValid(paraInfo_.kgexp, "kgexp", ge::DT_FLOAT, ge::FORMAT_ND,
149	            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.kDim});
150	    }
151	
152	    bool CheckValue() const
153	    {
154	        return IsSingleParamValid(paraInfo_.value, "value", ge::DT_FLOAT, ge::FORMAT_ND,
155	            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.vDim});
156	    }
157	
158	    bool CheckKCumdecay() const
159	    {
160	        return IsSingleParamValid(paraInfo_.kCumdecay, "k_cumdecay", ge::DT_FLOAT, ge::FORMAT_ND,
161	            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.kDim});
162	    }
163	
164	    bool CheckQgexp() const
165	    {
166	        return IsSingleParamValid(paraInfo_.qgexp, "qgexp", ge::DT_FLOAT, ge::FORMAT_ND,
167	            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.kDim});
