173	            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, 1});
174	    }
175	
176	    bool CheckActualSeqlens() const
177	    {
178	        return IsSingleParamValid(paraInfo_.actualSeqlens, "actual_seqlens", ge::DT_INT32, ge::FORMAT_ND,
179	            {shapeInfo_.batchNum});
