187	class ChunkGatedDeltaRuleRecurrenceTiling {
188	public:
189	    explicit ChunkGatedDeltaRuleRecurrenceTiling(gert::TilingContext* context) : context_(context) {}
190	
191	    ge::graphStatus ConvertContext()
192	    {
193	        if (context_->GetNodeName() == nullptr) {
194	            OPS_LOG_E("AiInfraChunkGatedDeltaRuleRecurrence", "opName got from TilingContext is nullptr");
195	            return ge::GRAPH_FAILED;
196	        }
197	
198	        SetParaInfo();
199	
200	        if (paraInfo_.workSpaces == nullptr) {
201	            OPS_LOG_E(paraInfo_.opName, "workSpaceSize got from ge is nullptr");
202	            return ge::GRAPH_FAILED;
203	        }
204	
205	        return ge::GRAPH_SUCCESS;
206	    }
207	    
208	    ge::graphStatus RunTiling()
209	    {
210	        // 获取硬件信息
211	        if (GetNpuInfo() != ge::GRAPH_SUCCESS) {
212	            OPS_LOG_E(context_->GetNodeName(), "GetNpuInfo failed!");
213	            return ge::GRAPH_FAILED;
214	        }
215	        // 获取shape大小
216	        if (SetShapeInfo() != ge::GRAPH_SUCCESS) {
217	            OPS_LOG_E(context_->GetNodeName(), "SetShapeInfo failed!");
218	            return ge::GRAPH_FAILED;
219	        }
220	        ChunkGatedDeltaRuleRecurrenceTilingCheck tilingCheck(paraInfo_, shapeInfo_);
221	        // 检查shape大小是否合法
222	        if (tilingCheck.CheckShapeInfo() != ge::GRAPH_SUCCESS) {
223	            OPS_LOG_E(context_->GetNodeName(), "CheckShapeInfo failed!");
224	            return ge::GRAPH_FAILED;
225	        }
226	        // 检查每个参数是否合法
227	        if (tilingCheck.CheckParaInfo() != ge::GRAPH_SUCCESS) {
228	            OPS_LOG_E(context_->GetNodeName(), "CheckParaInfo failed!");
229	            return ge::GRAPH_FAILED;
230	        }
231	        // 创建tilingKey(暂不启用)
232	        if (GenTilingKey() != ge::GRAPH_SUCCESS) {
233	            OPS_LOG_E(context_->GetNodeName(), "GenTilingKey failed!");
234	            return ge::GRAPH_FAILED;
235	        }
236	
237	        // 只需要系统 workspace，不需要申请用户 workspace（kernel只有原地修改）
238	        paraInfo_.workSpaces[0] = sysWorkspaceSize_;
239	
240	        // 当前有多少cube有多少用多少
241	        paraInfo_.blockDim = aicNum_;
242	
243	        return ge::GRAPH_SUCCESS;
244	    }
245	
246	    ge::graphStatus SetTilingData()
247	    {
248	        auto tilingData = context_->GetTilingData<ChunkGatedDeltaRuleRecurrenceTilingData>();
249	        if (tilingData == nullptr) {
250	            OPS_LOG_E(context_->GetNodeName(), "TilingData is nullptr.");
251	            return ge::GRAPH_FAILED;
252	        }
253	
254	        tilingData->batchNum = shapeInfo_.batchNum;
255	        tilingData->headNum = shapeInfo_.headNum;
256	        tilingData->kDim = shapeInfo_.kDim;
257	        tilingData->vDim = shapeInfo_.vDim;
258	        tilingData->chunkNum = shapeInfo_.chunkNum;
259	        tilingData->chunkSize = shapeInfo_.chunkSize;
260	        tilingData->enableMSplit = 0;
261	        tilingData->mSplitNum = 0;
262	
263	        uint32_t batchHead = shapeInfo_.batchNum * shapeInfo_.headNum;
264	
265	        if (batchHead >= aicNum_) {
266	            tilingData->enableMSplit = 0;
267	            context_->SetBlockDim(aicNum_);
268	        } else {
269	            uint32_t mSplitMaxNum = std::min(shapeInfo_.chunkSize, shapeInfo_.vDim) / BASEM;
270	            uint32_t mSplitNum = 0;
271	            for (uint32_t i = mSplitMaxNum; i >= 2; i >>= 1) { // 2表示：M轴按照2的整数次幂切分，2以下无意义（不切分）
272	                if (shapeInfo_.headNum * i <= aicNum_) {
273	                    mSplitNum = i;
274	                    break;
275	                }
276	            }
277	            // 条件：当batch * head大于 2 倍的head * M轴切分数时，说明AICore利用率够，不需要再切M轴
278	            if (batchHead > 2 * shapeInfo_.headNum * mSplitNum) {
279	                tilingData->enableMSplit = 0;
280	                context_->SetBlockDim(batchHead);
281	            } else {
282	                tilingData->enableMSplit = 1;
283	                tilingData->mSplitNum = mSplitNum;
284	                context_->SetBlockDim(shapeInfo_.headNum * mSplitNum);
285	            }
286	        }
287	
288	        context_->SetTilingKey(paraInfo_.tilingKey);
289	
290	        return ge::GRAPH_SUCCESS;
291	    }
