template <typename C>
std::string ConvertContainerToString(const C &container, const size_t size)
{
    std::stringstream ss;
    ss << "[";
    bool isFirst = true;
    for (size_t i = 0; i < size; i++) {
        if (!isFirst) {
            ss << ", ";
        }
        ss << std::to_string(container[i]);
        isFirst = false;
    }
    ss << "]";
    return ss.str();
}

class ChunkGatedDeltaRuleRecurrenceTilingCheck {
public:
    ChunkGatedDeltaRuleRecurrenceTilingCheck(
        const ChunkGatedDeltaRuleRecurrenceParaInfo &paraInfo,
        const ChunkGatedDeltaRuleRecurrenceShapeInfo &shapeInfo)
        : paraInfo_(paraInfo), shapeInfo_(shapeInfo) {}

    ge::graphStatus CheckParaInfo() const
    {
        if (!CheckInitialStateOut() || !CheckKgexp() || !CheckValue() ||
            !CheckKCumdecay() || !CheckQgexp() || !CheckGexp() || !CheckActualSeqlens()) {
            return ge::GRAPH_FAILED;
        }
        return ge::GRAPH_SUCCESS;
    }

    ge::graphStatus CheckShapeInfo() const
    {
        if (shapeInfo_.batchNum > MAX_B_SIZE) {
            OPS_LOG_E(paraInfo_.opName, "batchNum should not be greater than %u, got %u.",
                MAX_B_SIZE, shapeInfo_.batchNum);
            return ge::GRAPH_FAILED;
        }
        if (shapeInfo_.headNum > MAX_HV_SIZE) {
            OPS_LOG_E(paraInfo_.opName, "hvsize should not be greater than %u, got %u.",
                MAX_HV_SIZE, shapeInfo_.headNum);
            return ge::GRAPH_FAILED;
        }

        if (shapeInfo_.kDim != VALID_KDIM) {
            OPS_LOG_E(paraInfo_.opName, "dksize should be %u, got %u.", VALID_KDIM, shapeInfo_.kDim);
            return ge::GRAPH_FAILED;
        }

        if (shapeInfo_.vDim != VALID_VDIM) {
            OPS_LOG_E(paraInfo_.opName, "dvsize should be %u, got %u.", VALID_VDIM, shapeInfo_.headNum);
            return ge::GRAPH_FAILED;
        }

        const std::set<uint32_t> vaildChunkSize {32, 64, 128, 256};
        if (vaildChunkSize.find(shapeInfo_.chunkSize) == vaildChunkSize.end()) {
            OPS_LOG_E(paraInfo_.opName, "chunksize should not be of {32, 64, 128, 256}, got %u.",
                shapeInfo_.headNum);
            return ge::GRAPH_FAILED;
        }

        return ge::GRAPH_SUCCESS;
    }

private:
    static constexpr uint32_t MAX_B_SIZE = 65536U;
    static constexpr uint32_t MAX_HV_SIZE = 128U;
    static constexpr uint32_t VALID_KDIM = 128U;
    static constexpr uint32_t VALID_VDIM = 128U;
    static constexpr uint32_t N_CHUNKS_SIZE = 1;

    bool IsSingleParamValid(const RequiredParaInfo &param, const char *paramName,
        const ge::DataType expectedDtype, const ge::Format expectedFormat,
        const std::vector<size_t> &expectedDim) const
    {
        if((param.shape == nullptr) || (param.desc == nullptr)) {
            OPS_LOG_E(paraInfo_.opName, "%s should not be null.", paramName);
            return false;
        }

        ge::DataType dtype = param.desc->GetDataType();
        if (dtype != expectedDtype) {
            OPS_LOG_E(paraInfo_.opName, "%s datatype only supports %s, but got %s.", paramName,
                TypeUtils::DataTypeToSerialString(expectedDtype).c_str(),
                TypeUtils::DataTypeToSerialString(dtype).c_str());
            return false;
        }

        size_t dimNum = param.shape->GetStorageShape().GetDimNum();
        if (dimNum != expectedDim.size()) {
            OPS_LOG_E(paraInfo_.opName, "%s dim num supports only %zu, but got %zu.", paramName,
                expectedDim.size(), dimNum);
            return false;
        }

        for (size_t i = 0; i < dimNum; i++) {
            size_t dim = param.shape->GetStorageShape().GetDim(i);
            if (dim != expectedDim[i]) {
                OPS_LOG_E(paraInfo_.opName, "%s dim supports only %s, but got %s.", paramName,
                    ConvertContainerToString(expectedDim, expectedDim.size()).c_str(),
                    ConvertContainerToString(param.shape->GetStorageShape(), dimNum).c_str());
                return false;
            }
        }
        return true;
    }

    bool CheckInitialStateOut() const
    {
        return IsSingleParamValid(paraInfo_.initialStateOut, "initial_state_out", ge::DT_FLOAT, ge::FORMAT_ND,
            {shapeInfo_.batchNum, shapeInfo_.headNum, shapeInfo_.vDim, shapeInfo_.kDim});
    }

    bool CheckKgexp() const
    {
        return IsSingleParamValid(paraInfo_.kgexp, "kgexp", ge::DT_FLOAT, ge::FORMAT_ND,
            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.kDim});
    }

    bool CheckValue() const
    {
        return IsSingleParamValid(paraInfo_.value, "value", ge::DT_FLOAT, ge::FORMAT_ND,
            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.vDim});
    }

    bool CheckKCumdecay() const
    {
        return IsSingleParamValid(paraInfo_.kCumdecay, "k_cumdecay", ge::DT_FLOAT, ge::FORMAT_ND,
            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.kDim});
    }

    bool CheckQgexp() const
    {
        return IsSingleParamValid(paraInfo_.qgexp, "qgexp", ge::DT_FLOAT, ge::FORMAT_ND,
            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, shapeInfo_.kDim});
    }

    bool CheckGexp() const
    {
        return IsSingleParamValid(paraInfo_.gexp, "gexp", ge::DT_FLOAT, ge::FORMAT_ND,
            {shapeInfo_.headNum, shapeInfo_.chunkNum, shapeInfo_.chunkSize, 1});
    }

    bool CheckActualSeqlens() const
    {
        return IsSingleParamValid(paraInfo_.actualSeqlens, "actual_seqlens", ge::DT_INT32, ge::FORMAT_ND,
            {shapeInfo_.batchNum});
    }

    const ChunkGatedDeltaRuleRecurrenceParaInfo &paraInfo_;
    const ChunkGatedDeltaRuleRecurrenceShapeInfo &shapeInfo_;
};


class ChunkGatedDeltaRuleRecurrenceTiling {
public:
    explicit ChunkGatedDeltaRuleRecurrenceTiling(gert::TilingContext* context) : context_(context) {}

    ge::graphStatus ConvertContext()
    {
        if (context_->GetNodeName() == nullptr) {
            OPS_LOG_E("AiInfraChunkGatedDeltaRuleRecurrence", "opName got from TilingContext is nullptr");
            return ge::GRAPH_FAILED;
        }

        SetParaInfo();

        if (paraInfo_.workSpaces == nullptr) {
            OPS_LOG_E(paraInfo_.opName, "workSpaceSize got from ge is nullptr");
            return ge::GRAPH_FAILED;
        }

        return ge::GRAPH_SUCCESS;
    }

    ge::graphStatus RunTiling()
    {
        // 获取硬件信息
        if (GetNpuInfo() != ge::GRAPH_SUCCESS) {
            OPS_LOG_E(context_->GetNodeName(), "GetNpuInfo failed!");
            return ge::GRAPH_FAILED;
        }
        // 获取shape大小
        if (SetShapeInfo() != ge::GRAPH_SUCCESS) {
            OPS_LOG_E(context_->GetNodeName(), "SetShapeInfo failed!");
            return ge::GRAPH_FAILED;
        }
        ChunkGatedDeltaRuleRecurrenceTilingCheck tilingCheck(paraInfo_, shapeInfo_);
        // 检查shape大小是否合法
        if (tilingCheck.CheckShapeInfo() != ge::GRAPH_SUCCESS) {
            OPS_LOG_E(context_->GetNodeName(), "CheckShapeInfo failed!");
            return ge::GRAPH_FAILED;
        }
        // 检查每个参数是否合法
        if (tilingCheck.CheckParaInfo() != ge::GRAPH_SUCCESS) {
            OPS_LOG_E(context_->GetNodeName(), "CheckParaInfo failed!");
            return ge::GRAPH_FAILED;
        }
        // 创建tilingKey(暂不启用)
        if (GenTilingKey() != ge::GRAPH_SUCCESS) {
            OPS_LOG_E(context_->GetNodeName(), "GenTilingKey failed!");
            return ge::GRAPH_FAILED;
        }

        // 只需要系统 workspace，不需要申请用户 workspace（kernel只有原地修改）
        paraInfo_.workSpaces[0] = sysWorkspaceSize_;

        // 当前有多少cube有多少用多少
        paraInfo_.blockDim = aicNum_;

        return ge::GRAPH_SUCCESS;
    }

    ge::graphStatus SetTilingData()
    {
        auto tilingData = context_->GetTilingData<ChunkGatedDeltaRuleRecurrenceTilingData>();
        if (tilingData == nullptr) {
            OPS_LOG_E(context_->GetNodeName(), "TilingData is nullptr.");
            return ge::GRAPH_FAILED;
        }

        tilingData->batchNum = shapeInfo_.batchNum;
        tilingData->headNum = shapeInfo_.headNum;
        tilingData->kDim = shapeInfo_.kDim;
        tilingData->vDim = shapeInfo_.vDim;
        tilingData->chunkNum = shapeInfo_.chunkNum;
        tilingData->chunkSize = shapeInfo_.chunkSize;
        tilingData->enableMSplit = 0;
        tilingData->mSplitNum = 0;

        uint32_t batchHead = shapeInfo_.batchNum * shapeInfo_.headNum;

        if (batchHead >= aicNum_) {
            tilingData->enableMSplit = 0;
            context_->SetBlockDim(aicNum_);
        } else {
            uint32_t mSplitMaxNum = std::min(shapeInfo_.chunkSize, shapeInfo_.vDim) / BASEM;
            uint32_t mSplitNum = 0;
            for (uint32_t i = mSplitMaxNum; i >= 2; i >>= 1) { // 2表示：M轴按照2的整数次幂切分，2以下无意义（不切分）
                if (shapeInfo_.headNum * i <= aicNum_) {
                    mSplitNum = i;
                    break;
                }
            }
            // 条件：当batch * head大于 2 倍的head * M轴切分数时，说明AICore利用率够，不需要再切M轴
            if (batchHead > 2 * shapeInfo_.headNum * mSplitNum) {
                tilingData->enableMSplit = 0;
                context_->SetBlockDim(batchHead);
            } else {
                tilingData->enableMSplit = 1;
                tilingData->mSplitNum = mSplitNum;
                context_->SetBlockDim(shapeInfo_.headNum * mSplitNum);
            }
        }

        context_->SetTilingKey(paraInfo_.tilingKey);

        return ge::GRAPH_SUCCESS;
    }

private:
    uint32_t aicNum_ = 0;
    uint32_t aivNum_ = 0;
    size_t sysWorkspaceSize_ = 0;

    ChunkGatedDeltaRuleRecurrenceShapeInfo shapeInfo_ = {};
    ChunkGatedDeltaRuleRecurrenceParaInfo paraInfo_ = {};
    gert::TilingContext* context_ = nullptr;

    static  constexpr uint32_t BASEM = 16;

    // INPUT INDEX
    static constexpr uint32_t INITIAL_STATE_INPUT_INDEX = 0;
    static constexpr uint32_t KGEXP_INPUT_INDEX = 1;
    static constexpr uint32_t VALUE_INPUT_INDEX = 2;
    static constexpr uint32_t K_CUMDECAY_INPUT_INDEX = 3;
    static constexpr uint32_t QGEXP_INPUT_INDEX = 4;
    static constexpr uint32_t GEXP_INPUT_INDEX = 5;
    static constexpr uint32_t ACTUAL_SEQLENS_INPUT_INDEX = 6;

    // OUTPUT INDEX
    static constexpr uint32_t INITIAL_STATE_OUTPUT_INDEX = 0;
    static constexpr uint32_t ATTN_INTER_OUT_OUTPUT_INDEX = 1;
    static constexpr uint32_t V_NEW_OUT_OUTPUT_INDEX = 2;

    void SetParaInfo()
    {
        paraInfo_.opName = context_->GetNodeName();
        paraInfo_.opType = context_->GetNodeType();
        paraInfo_.platformInfo = context_->GetPlatformInfo();
        paraInfo_.workSpaces = context_->GetWorkspaceSizes(1);

        paraInfo_.initialState.desc = context_->GetRequiredInputDesc(INITIAL_STATE_INPUT_INDEX);
        paraInfo_.initialState.shape = context_->GetRequiredInputShape(INITIAL_STATE_INPUT_INDEX);
        paraInfo_.kgexp.desc = context_->GetRequiredInputDesc(KGEXP_INPUT_INDEX);
        paraInfo_.kgexp.shape = context_->GetRequiredInputShape(KGEXP_INPUT_INDEX);
        paraInfo_.value.desc = context_->GetRequiredInputDesc(VALUE_INPUT_INDEX);
        paraInfo_.value.shape = context_->GetRequiredInputShape(VALUE_INPUT_INDEX);
        paraInfo_.kCumdecay.desc = context_->GetRequiredInputDesc(K_CUMDECAY_INPUT_INDEX);
        paraInfo_.kCumdecay.shape = context_->GetRequiredInputShape(K_CUMDECAY_INPUT_INDEX);
        paraInfo_.qgexp.desc = context_->GetRequiredInputDesc(QGEXP_INPUT_INDEX);
        paraInfo_.qgexp.shape = context_->GetRequiredInputShape(QGEXP_INPUT_INDEX);
        paraInfo_.gexp.desc = context_->GetRequiredInputDesc(GEXP_INPUT_INDEX);
        paraInfo_.gexp.shape = context_->GetRequiredInputShape(GEXP_INPUT_INDEX);
        paraInfo_.actualSeqlens.desc = context_->GetRequiredInputDesc(ACTUAL_SEQLENS_INPUT_INDEX);
        paraInfo_.actualSeqlens.shape = context_->GetRequiredInputShape(ACTUAL_SEQLENS_INPUT_INDEX);

        paraInfo_.initialStateOut.desc = context_->GetOutputDesc(INITIAL_STATE_OUTPUT_INDEX);
        paraInfo_.initialStateOut.shape = context_->GetOutputShape(INITIAL_STATE_OUTPUT_INDEX);
        paraInfo_.attnInterOut.desc = context_->GetOutputDesc(ATTN_INTER_OUT_OUTPUT_INDEX);
        paraInfo_.attnInterOut.shape = context_->GetOutputShape(ATTN_INTER_OUT_OUTPUT_INDEX);
        paraInfo_.vNewOut.desc = context_->GetOutputDesc(V_NEW_OUT_OUTPUT_INDEX);
        paraInfo_.vNewOut.shape = context_->GetOutputShape(V_NEW_OUT_OUTPUT_INDEX);
    }

    ge::graphStatus SetShapeInfo()
    {
        // initial_state [b, hv, dv, dk]
        shapeInfo_.batchNum = paraInfo_.initialState.shape->GetStorageShape().GetDim(0);  // 0
        shapeInfo_.headNum = paraInfo_.initialState.shape->GetStorageShape().GetDim(1);   // 1
        shapeInfo_.vDim = paraInfo_.initialState.shape->GetStorageShape().GetDim(2);      // 2
        shapeInfo_.kDim = paraInfo_.initialState.shape->GetStorageShape().GetDim(3);      // 3

        // kgexp [hv, n_chunk, chunk_size, dk]
        shapeInfo_.chunkNum = paraInfo_.kgexp.shape->GetStorageShape().GetDim(1);         // 1
        shapeInfo_.chunkSize = paraInfo_.kgexp.shape->GetStorageShape().GetDim(2);        // 2

        return ge::GRAPH_SUCCESS;
    }

    ge::graphStatus GetNpuInfo()
    {
        if (paraInfo_.platformInfo == nullptr) {
            OPS_LOG_E(paraInfo_.opName, "GetPlatformInfo is nullptr.");
            return ge::GRAPH_FAILED;
        }

        auto platformInfo = platform_ascendc::PlatformAscendC(paraInfo_.platformInfo);

        sysWorkspaceSize_ = platformInfo.GetLibApiWorkSpaceSize();
        aivNum_ = platformInfo.GetCoreNumAiv();
        aicNum_ = platformInfo.GetCoreNumAic();
        if (aicNum_ == 0 || aivNum_ == 0) {
            OPS_LOG_E(paraInfo_.opName, "num of core obtained is 0.");
            return ge::GRAPH_FAILED;
        }

        return ge::GRAPH_SUCCESS;
    }

    // 目前tilingKey 设置为默认
    ge::graphStatus GenTilingKey()
    {
        // GET_TPL_TILING_KEY需要自己实现，在kernel
        paraInfo_.tilingKey = 0;
        OPS_LOG_I(paraInfo_.opName, "TilingKey: %lu", paraInfo_.tilingKey);
        return ge::GRAPH_SUCCESS;
    }
};

ge::graphStatus TilingChunkGatedDeltaRuleRecurrence(gert::TilingContext *context)
{
    if (context == nullptr) {
        OPS_LOG_E("AiInfraChunkGatedDeltaRuleRecurrence", "Context is nullptr.");
        return ge::GRAPH_FAILED;
    }

    ChunkGatedDeltaRuleRecurrenceTiling tiling(context);
    if (tiling.ConvertContext() != ge::GRAPH_SUCCESS) {
        OPS_LOG_E(context->GetNodeName(),
            "Error occurred while converting tilingContext to ChunkGatedDeltaRuleRecurrenceTiling.context_");
        return ge::GRAPH_FAILED;
    }

    if (tiling.RunTiling() != ge::SUCCESS) {
        OPS_LOG_E(context->GetNodeName(), "Error occurred while check");
        return ge::GRAPH_FAILED;
    }

    if (tiling.SetTilingData() != ge::GRAPH_SUCCESS) {
        OPS_LOG_E(context->GetNodeName(), "Error occurred while set tilingData");
        return ge::GRAPH_FAILED;
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus TilingPrepareForChunkGatedDeltaRuleRecurrence(gert::TilingParseContext *context)
{
    (void)context;
    return ge::GRAPH_SUCCESS;
}

IMPL_OP_OPTILING(AiInfraChunkGatedDeltaRuleRecurrence)
    .Tiling(TilingChunkGatedDeltaRuleRecurrence)
    .TilingParse<ChunkGatedDeltaRuleRecurrenceCompileInfo>(TilingPrepareForChunkGatedDeltaRuleRecurrence);

}

