23	template <typename DTYPE>
24	class KernelAiInfraFusedCausalConv1dUpdate : public KernelAiInfraFusedCausalConv1dBase<DTYPE> {
25	public:
26	    __aicore__ inline KernelAiInfraFusedCausalConv1dUpdate(TPipe *pipe, const AiInfraFusedCausalConv1dTilingData *tiling)
27	        : KernelAiInfraFusedCausalConv1dBase<DTYPE>(pipe, tiling)
28	    {}
29	
30	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR weight, GM_ADDR conv_states, GM_ADDR query_start_loc,
31	        GM_ADDR cache_indices, GM_ADDR num_accepted_tokens, GM_ADDR num_computed_tokens,
32	        GM_ADDR block_idx_first_scheduled_token, GM_ADDR block_idx_last_scheduled_token, GM_ADDR initial_state_idx,
33	        GM_ADDR y)
34	    {
35	        // Parse tiling data
36	        baseDim_ = this->tilingData_->baseDim;
37	        coreDimAct_ = this->tilingData_->coreDimAct;
38	        baseBatch_ = this->tilingData_->baseBatch;
39	        coreBatchAct_ = this->tilingData_->coreBatchAct;
40	        multiTokenNum_ = this->tilingData_->multiTokenNum;  // m
41	        windowSize_ = this->tilingData_->windowSize;
42	        dimSize_ = this->tilingData_->dimSize;
43	        stateLen_ = this->tilingData_->stateLen;
44	
45	        // For non-contiguous tensor
46	        xStride0_ = this->tilingData_->xStride0;
47	        xStride1_ = this->tilingData_->xStride1;
48	        convStatesStride0_ = this->tilingData_->convStateStride0;
49	        convStatesStride1_ = this->tilingData_->convStateStride1;
50	
51	        apcEnable_ = this->tilingData_->apcEnable;
52	        convMode_ = this->tilingData_->convMode;
53	        blockSize_ = this->tilingData_->blockSize;
54	        maxNumBlocks_ = this->tilingData_->maxNumBlocks;
55	
56	        // For tail core
57	        blockIdx_ = static_cast<int64_t>(GetBlockIdx());
58	        curDim_ = ((blockIdx_ + NUM_ONE) % coreDimAct_ == 0) ? this->tilingData_->tailDim : this->tilingData_->baseDim;
59	        curBatch_ = (blockIdx_ >= (coreBatchAct_ - NUM_ONE) * coreDimAct_) ? this->tilingData_->tailBatch
60	                                                                           : this->tilingData_->baseBatch;
61	        seqLen_ = multiTokenNum_ + NUM_ONE;                      // m+1 三维输入时seq_len固定
62	        stateLen_ = windowSize_ - NUM_ONE + multiTokenNum_;      // width-1+m = 2+m
63	        curDimGmOffset_ = (blockIdx_ % coreDimAct_) * baseDim_;  // 当前核处理的dim维度的起始索引（对于Gm）
64	        isXDimSizeTwo_ = this->tilingData_->xDimSize == NUM_TWO;
65	
66	        // Set global buffers
67	        this->xGm.SetGlobalBuffer((__gm__ DTYPE *)x);
68	        this->weightGm.SetGlobalBuffer((__gm__ DTYPE *)weight);
69	        this->convStateGm.SetGlobalBuffer((__gm__ DTYPE *)conv_states);
70	        if (this->tilingData_->hasCacheIndices) {
71	            this->cacheIndicesGm.SetGlobalBuffer((__gm__ int32_t *)cache_indices);
72	        }
73	        if (this->tilingData_->hasNumAcceptedTokens) {
74	            this->numAcceptedTokensGm.SetGlobalBuffer((__gm__ int32_t *)num_accepted_tokens);
75	            hasNumAcceptedTokens_ = true;
76	        }
77	        if (isXDimSizeTwo_) {
78	            this->queryStartLocGm.SetGlobalBuffer((__gm__ int32_t *)query_start_loc);
79	        }
80	        if (this->tilingData_->hasNumComputedTokens) {
81	            this->numComputedTokensGm.SetGlobalBuffer((__gm__ int32_t *)num_computed_tokens);
82	            hasNumComputedTokens_ = true;
83	        }
84	        if (apcEnable_) {
85	            this->blockIdxFirstScheduledTokenGm.SetGlobalBuffer((__gm__ int32_t *)block_idx_first_scheduled_token);
86	            this->blockIdxLastScheduledTokenGm.SetGlobalBuffer((__gm__ int32_t *)block_idx_last_scheduled_token);
87	            this->initialStateIdxGm.SetGlobalBuffer((__gm__ int32_t *)initial_state_idx);
88	        }
89	        this->outGm.SetGlobalBuffer((__gm__ DTYPE *)y);
90	
91	        this->pipe_->InitBuffer(xQueue_, DOUBLE_BUFFER_NUM, curDim_ * sizeof(DTYPE));
92	        this->pipe_->InitBuffer(weightQueue_, NUM_ONE, windowSize_ * curDim_ * sizeof(float));
93	        this->pipe_->InitBuffer(convStatesQueue_, NUM_ONE, stateLen_ * curDim_ * sizeof(DTYPE));
94	        this->pipe_->InitBuffer(outputQueue_, NUM_ONE, curDim_ * sizeof(DTYPE));
95	
96	        // Tmp buffers for computation
97	        this->pipe_->InitBuffer(y0Buf_, curDim_ * sizeof(float));  // 存储y0
98	        this->pipe_->InitBuffer(y1Buf_, curDim_ * sizeof(float));  // 存储y1
99	        this->pipe_->InitBuffer(xBuf_, curDim_ * sizeof(float));
100	        this->pipe_->InitBuffer(y2Buf_, curDim_ * sizeof(float));
101	    }
102	
103	    __aicore__ inline void Process()
104	    {
105	        CopyInWeight();  // 搬入weight、原地cast、w2+1残差操作
106	        int64_t firstBatchIdxOnCore = (blockIdx_ / coreDimAct_) * baseBatch_;  // 当前核处理的起始token 在整个X上的索引
107	        if (isXDimSizeTwo_) {
108	            tokenIdx_ = static_cast<int64_t>(this->queryStartLocGm(firstBatchIdxOnCore));
109	        }
110	        for (int64_t idxB = 0; idxB < curBatch_; idxB++) {
111	            // 对每个batch处理
112	            int64_t batchIdx = firstBatchIdxOnCore + idxB;  // 当前batch在整个GM Tensor上的索引
113	            if (isXDimSizeTwo_) {
114	                seqLen_ = static_cast<int64_t>(this->queryStartLocGm(batchIdx + 1)) - tokenIdx_;
115	            }
116	            CalRunningCacheRWIdx(batchIdx);  // 计算读写running cache的索引
117	            if (readCacheLine_ == this->tilingData_->padSlotId) {
118	                if (isXDimSizeTwo_) {
119	                    tokenIdx_ = static_cast<int64_t>(
120	                        this->queryStartLocGm(batchIdx + 1));  // 前进跳过这个 pad batch 对应的所有 token
121	                }
122	                continue;
123	            }
124	            CopyInConvState(batchIdx);           // 读cache
125	            CopyOutConvStateRunCache();          // 写running cache中原本就是cache的部分
126	            CopyOutConvStatePreCache(batchIdx);  // 写prefix cache中原本就是cache的部分
127	            InitY();                             // 对y0和y1初始化
128	            if (convMode_) {                     // 计算置0索引
129	                lastResetIdx_ = NUM_TWO - numComputedToken_;
130	                lastResetIdx_ = lastResetIdx_ > 0 ? lastResetIdx_ : 0;
131	                lastResetIdx_ = lastResetIdx_ > seqLen_ ? seqLen_ : lastResetIdx_;
132	            }
133	            for (int64_t idxS = 0; idxS < seqLen_; idxS++) {  // 对每个seq处理
134	                CopyInX(batchIdx, idxS);                      // 搬入curDim的x并cast到xBuf
135	                CopyOutXRunCache(idxS);                       // 写cache，复用xQue
136	                CopyOutXPreCache(batchIdx, idxS);             // 写cache，复用xQue
137	                ComputeAndUpdate(idxS);                       // 计算并更新y0y1
138	                CopyOutY(batchIdx, idxS);                     // 搬出卷积结果
139	                if (isXDimSizeTwo_) {
140	                    tokenIdx_++;
141	                }
142	            }
143	        }
144	        weightQueue_.FreeTensor(weight32Local_);  // 和CopyInWeight()的AllocTensor对应
145	    }
146	
147	private:
148	    __aicore__ inline void CopyInWeight()
149	    {
150	        weight32Local_ = weightQueue_.AllocTensor<float>();
151	        DataCopyExtParams copyParams;
152	        copyParams.blockCount = static_cast<uint16_t>(windowSize_);
153	        copyParams.blockLen = static_cast<uint32_t>(curDim_ * sizeof(DTYPE));
154	        copyParams.srcStride = static_cast<uint32_t>((dimSize_ - curDim_) * sizeof(DTYPE));
155	        copyParams.dstStride = static_cast<uint32_t>(0);
156	        DataCopyPadExtParams<DTYPE> padParams{false, 0, 0, 0};
157	        LocalTensor<DTYPE> weight16Local = weight32Local_.ReinterpretCast<DTYPE>();
158	        DataCopyPad(weight16Local[NUM_THREE * curDim_], this->weightGm[curDimGmOffset_], copyParams, padParams);
159	
160	        weightQueue_.EnQue(weight16Local);
161	        weight16Local = weightQueue_.DeQue<DTYPE>();
162	
163	        Cast<float, DTYPE>(weight32Local_, weight16Local[NUM_THREE * curDim_],
164	            RoundMode::CAST_NONE, curDim_ * windowSize_);
165	        PipeBarrier<PIPE_V>();
166	        if (this->tilingData_->residual == NUM_ONE) {
167	            Adds(weight32Local_[NUM_TWO * curDim_], weight32Local_[NUM_TWO * curDim_], 1.0f, curDim_);
168	            PipeBarrier<PIPE_V>();
169	        }

