template <typename DTYPE>
class KernelAiInfraFusedCausalConv1dUpdate : public KernelAiInfraFusedCausalConv1dBase<DTYPE> {
public:
    __aicore__ inline KernelAiInfraFusedCausalConv1dUpdate(TPipe *pipe, const AiInfraFusedCausalConv1dTilingData *tiling)
        : KernelAiInfraFusedCausalConv1dBase<DTYPE>(pipe, tiling)
    {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR weight, GM_ADDR conv_states, GM_ADDR query_start_loc,
        GM_ADDR cache_indices, GM_ADDR num_accepted_tokens, GM_ADDR num_computed_tokens,
        GM_ADDR block_idx_first_scheduled_token, GM_ADDR block_idx_last_scheduled_token, GM_ADDR initial_state_idx,
        GM_ADDR y)
    {
        // Parse tiling data
        baseDim_ = this->tilingData_->baseDim;
        coreDimAct_ = this->tilingData_->coreDimAct;
        baseBatch_ = this->tilingData_->baseBatch;
        coreBatchAct_ = this->tilingData_->coreBatchAct;
        multiTokenNum_ = this->tilingData_->multiTokenNum;  // m
        windowSize_ = this->tilingData_->windowSize;
        dimSize_ = this->tilingData_->dimSize;
        stateLen_ = this->tilingData_->stateLen;

        // For non-contiguous tensor
        xStride0_ = this->tilingData_->xStride0;
        xStride1_ = this->tilingData_->xStride1;
        convStatesStride0_ = this->tilingData_->convStateStride0;
        convStatesStride1_ = this->tilingData_->convStateStride1;

        apcEnable_ = this->tilingData_->apcEnable;
        convMode_ = this->tilingData_->convMode;
        blockSize_ = this->tilingData_->blockSize;
        maxNumBlocks_ = this->tilingData_->maxNumBlocks;

        // For tail core
        blockIdx_ = static_cast<int64_t>(GetBlockIdx());
        curDim_ = ((blockIdx_ + NUM_ONE) % coreDimAct_ == 0) ? this->tilingData_->tailDim : this->tilingData_->baseDim;
        curBatch_ = (blockIdx_ >= (coreBatchAct_ - NUM_ONE) * coreDimAct_) ? this->tilingData_->tailBatch
                                                                           : this->tilingData_->baseBatch;
        seqLen_ = multiTokenNum_ + NUM_ONE;                      // m+1 三维输入时seq_len固定
        stateLen_ = windowSize_ - NUM_ONE + multiTokenNum_;      // width-1+m = 2+m
        curDimGmOffset_ = (blockIdx_ % coreDimAct_) * baseDim_;  // 当前核处理的dim维度的起始索引（对于Gm）
        isXDimSizeTwo_ = this->tilingData_->xDimSize == NUM_TWO;

        // Set global buffers
        this->xGm.SetGlobalBuffer((__gm__ DTYPE *)x);
        this->weightGm.SetGlobalBuffer((__gm__ DTYPE *)weight);
        this->convStateGm.SetGlobalBuffer((__gm__ DTYPE *)conv_states);
        if (this->tilingData_->hasCacheIndices) {
            this->cacheIndicesGm.SetGlobalBuffer((__gm__ int32_t *)cache_indices);
        }
        if (this->tilingData_->hasNumAcceptedTokens) {
            this->numAcceptedTokensGm.SetGlobalBuffer((__gm__ int32_t *)num_accepted_tokens);
            hasNumAcceptedTokens_ = true;
        }
        if (isXDimSizeTwo_) {
            this->queryStartLocGm.SetGlobalBuffer((__gm__ int32_t *)query_start_loc);
        }
        if (this->tilingData_->hasNumComputedTokens) {
            this->numComputedTokensGm.SetGlobalBuffer((__gm__ int32_t *)num_computed_tokens);
            hasNumComputedTokens_ = true;
        }
        if (apcEnable_) {
            this->blockIdxFirstScheduledTokenGm.SetGlobalBuffer((__gm__ int32_t *)block_idx_first_scheduled_token);
            this->blockIdxLastScheduledTokenGm.SetGlobalBuffer((__gm__ int32_t *)block_idx_last_scheduled_token);
            this->initialStateIdxGm.SetGlobalBuffer((__gm__ int32_t *)initial_state_idx);
        }
        this->outGm.SetGlobalBuffer((__gm__ DTYPE *)y);

        this->pipe_->InitBuffer(xQueue_, DOUBLE_BUFFER_NUM, curDim_ * sizeof(DTYPE));
        this->pipe_->InitBuffer(weightQueue_, NUM_ONE, windowSize_ * curDim_ * sizeof(float));
        this->pipe_->InitBuffer(convStatesQueue_, NUM_ONE, stateLen_ * curDim_ * sizeof(DTYPE));
        this->pipe_->InitBuffer(outputQueue_, NUM_ONE, curDim_ * sizeof(DTYPE));

        // Tmp buffers for computation
        this->pipe_->InitBuffer(y0Buf_, curDim_ * sizeof(float));  // 存储y0
        this->pipe_->InitBuffer(y1Buf_, curDim_ * sizeof(float));  // 存储y1
        this->pipe_->InitBuffer(xBuf_, curDim_ * sizeof(float));
        this->pipe_->InitBuffer(y2Buf_, curDim_ * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        CopyInWeight();  // 搬入weight、原地cast、w2+1残差操作
        int64_t firstBatchIdxOnCore = (blockIdx_ / coreDimAct_) * baseBatch_;  // 当前核处理的起始token 在整个X上的索引
        if (isXDimSizeTwo_) {
            tokenIdx_ = static_cast<int64_t>(this->queryStartLocGm(firstBatchIdxOnCore));
        }
        for (int64_t idxB = 0; idxB < curBatch_; idxB++) {
            // 对每个batch处理
            int64_t batchIdx = firstBatchIdxOnCore + idxB;  // 当前batch在整个GM Tensor上的索引
            if (isXDimSizeTwo_) {
                seqLen_ = static_cast<int64_t>(this->queryStartLocGm(batchIdx + 1)) - tokenIdx_;
            }
            CalRunningCacheRWIdx(batchIdx);  // 计算读写running cache的索引
            if (readCacheLine_ == this->tilingData_->padSlotId) {
                if (isXDimSizeTwo_) {
                    tokenIdx_ = static_cast<int64_t>(
                        this->queryStartLocGm(batchIdx + 1));  // 前进跳过这个 pad batch 对应的所有 token
                }
                continue;
            }
            CopyInConvState(batchIdx);           // 读cache
            CopyOutConvStateRunCache();          // 写running cache中原本就是cache的部分
            CopyOutConvStatePreCache(batchIdx);  // 写prefix cache中原本就是cache的部分
            InitY();                             // 对y0和y1初始化
            if (convMode_) {                     // 计算置0索引
                lastResetIdx_ = NUM_TWO - numComputedToken_;
                lastResetIdx_ = lastResetIdx_ > 0 ? lastResetIdx_ : 0;
                lastResetIdx_ = lastResetIdx_ > seqLen_ ? seqLen_ : lastResetIdx_;
            }
            for (int64_t idxS = 0; idxS < seqLen_; idxS++) {  // 对每个seq处理
                CopyInX(batchIdx, idxS);                      // 搬入curDim的x并cast到xBuf
                CopyOutXRunCache(idxS);                       // 写cache，复用xQue
                CopyOutXPreCache(batchIdx, idxS);             // 写cache，复用xQue
                ComputeAndUpdate(idxS);                       // 计算并更新y0y1
                CopyOutY(batchIdx, idxS);                     // 搬出卷积结果
                if (isXDimSizeTwo_) {
                    tokenIdx_++;
                }
            }
        }
        weightQueue_.FreeTensor(weight32Local_);  // 和CopyInWeight()的AllocTensor对应
    }

private:
    __aicore__ inline void CopyInWeight()
    {
        weight32Local_ = weightQueue_.AllocTensor<float>();
        DataCopyExtParams copyParams;
        copyParams.blockCount = static_cast<uint16_t>(windowSize_);
        copyParams.blockLen = static_cast<uint32_t>(curDim_ * sizeof(DTYPE));
        copyParams.srcStride = static_cast<uint32_t>((dimSize_ - curDim_) * sizeof(DTYPE));
        copyParams.dstStride = static_cast<uint32_t>(0);
        DataCopyPadExtParams<DTYPE> padParams{false, 0, 0, 0};
        LocalTensor<DTYPE> weight16Local = weight32Local_.ReinterpretCast<DTYPE>();
        DataCopyPad(weight16Local[NUM_THREE * curDim_], this->weightGm[curDimGmOffset_], copyParams, padParams);

        weightQueue_.EnQue(weight16Local);
        weight16Local = weightQueue_.DeQue<DTYPE>();

        Cast<float, DTYPE>(weight32Local_, weight16Local[NUM_THREE * curDim_],
            RoundMode::CAST_NONE, curDim_ * windowSize_);
        PipeBarrier<PIPE_V>();
        if (this->tilingData_->residual == NUM_ONE) {
            Adds(weight32Local_[NUM_TWO * curDim_], weight32Local_[NUM_TWO * curDim_], 1.0f, curDim_);
            PipeBarrier<PIPE_V>();
        }

