namespace AiInfraFusedCausalConv1d {
using namespace AscendC;
template <typename DTYPE>
class KernelAiInfraFusedCausalConv1dFnCutbsd : public KernelAiInfraFusedCausalConv1dBase<DTYPE> {
public:
    __aicore__ inline KernelAiInfraFusedCausalConv1dFnCutbsd(TPipe *pipe, const AiInfraFusedCausalConv1dTilingData *tiling)
        : KernelAiInfraFusedCausalConv1dBase<DTYPE>(pipe, tiling)
    {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR weight, GM_ADDR conv_states, GM_ADDR query_start_loc,
        GM_ADDR cache_indices, GM_ADDR num_accepted_tokens, GM_ADDR num_computed_tokens,
        GM_ADDR block_idx_first_scheduled_token, GM_ADDR block_idx_last_scheduled_token, GM_ADDR initial_state_idx,
        GM_ADDR output)
    {
        this->xGm.SetGlobalBuffer((__gm__ DTYPE *)x);            //  [cuSeqLen, dimSize]
        this->weightGm.SetGlobalBuffer((__gm__ DTYPE *)weight);  //  [3, dimSize]
        this->convStateGm.SetGlobalBuffer((__gm__ DTYPE *)conv_states);
        this->queryStartLocGm.SetGlobalBuffer((__gm__ int32_t *)query_start_loc);
        if (this->tilingData_->hasCacheIndices) {
            this->cacheIndicesGm.SetGlobalBuffer((__gm__ int32_t *)cache_indices);
        }
        if (this->tilingData_->hasNumAcceptedTokens) {
            this->numAcceptedTokensGm.SetGlobalBuffer((__gm__ int32_t *)num_accepted_tokens);
        }
        if (this->tilingData_->hasNumComputedTokens) {
            this->numComputedTokensGm.SetGlobalBuffer((__gm__ int32_t *)num_computed_tokens);
        }
        if (this->tilingData_->apcEnable) {
            this->blockIdxFirstScheduledTokenGm.SetGlobalBuffer((__gm__ int32_t *)block_idx_first_scheduled_token);
            this->blockIdxLastScheduledTokenGm.SetGlobalBuffer((__gm__ int32_t *)block_idx_last_scheduled_token);
            this->initialStateIdxGm.SetGlobalBuffer((__gm__ int32_t *)initial_state_idx);
        }
        this->outGm.SetGlobalBuffer((__gm__ DTYPE *)output);  //  [cuSeqLen, dimSize]

        // 计算当前核需要处理的dim片段和token数
        this->baseDimIdx = GetBlockIdx() % this->tilingData_->baseDimCnt;
        this->baseblockFactorIdx = (GetBlockIdx() / this->tilingData_->baseDimCnt) % this->tilingData_->blockCnt;

        // 处理尾块
        this->curBlockFactor = this->baseblockFactorIdx == this->tilingData_->blockCnt - NUM_ONE
                                   ? this->tilingData_->blockFactorTail
                                   : this->tilingData_->blockFactor;
        this->curBaseDim = this->baseDimIdx == this->tilingData_->baseDimCnt - NUM_ONE ? this->tilingData_->baseDimTail
                                                                                       : this->tilingData_->baseDim;

        // Calc token start pos
        this->tokenIdx = this->baseblockFactorIdx * this->tilingData_->blockFactor;
        this->batchId = this->FindBIdx(this->tokenIdx);
        this->seqIdStart = this->queryStartLocGm.GetValue(this->batchId);
        this->seqIdEnd = this->queryStartLocGm.GetValue(this->batchId + NUM_ONE);
        this->seqId = this->tokenIdx - this->seqIdStart;
        this->seqLen = this->seqIdEnd - this->seqIdStart;

        // max baseDim = 5136
        this->pipe_->InitBuffer(
            this->inQueueX, DOUBLE_BUFFER_NUM, this->tilingData_->baseDim * sizeof(DTYPE));  // 2 * baseDim * 2 / 1024
        this->pipe_->InitBuffer(
            this->inQueueW, NUM_ONE, NUM_THREE * this->tilingData_->baseDim * sizeof(float));  // 3 * baseDim * 4 / 1024
        this->pipe_->InitBuffer(this->y2, this->tilingData_->baseDim * sizeof(float));         // baseDim * 4 / 1024
        this->pipe_->InitBuffer(this->y1, this->tilingData_->baseDim * sizeof(float));         // baseDim * 4 / 1024
        this->pipe_->InitBuffer(this->y0, this->tilingData_->baseDim * sizeof(float));         // baseDim * 4 / 1024
        this->pipe_->InitBuffer(this->xFp32, this->tilingData_->baseDim * sizeof(float));      // baseDim * 4 / 1024
        this->pipe_->InitBuffer(this->convStatesQue,
            DOUBLE_BUFFER_NUM,
            this->tilingData_->baseDim * sizeof(DTYPE));  // 2 * baseDim * 2 / 1024
        this->pipe_->InitBuffer(
            this->outQueue, NUM_ONE, this->tilingData_->baseDim * sizeof(DTYPE));  //  baseDim * 2 / 1024
    }

    __aicore__ inline void Process()
    {
        // Load weight
        LocalTensor<float> weightFp32 = this->inQueueW.template AllocTensor<float>();
        LocalTensor<DTYPE> localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->curBaseDim];
        LocalTensor<DTYPE> localW1 = localW0[this->curBaseDim * NUM_TWO];
        LocalTensor<DTYPE> localW2 = localW1[this->curBaseDim * NUM_TWO];
        DataCopyPadExtParams<DTYPE> padParams{false, 0, 0, 0};
        DataCopyExtParams copyParamsContiguous;
        copyParamsContiguous.blockCount = NUM_THREE;  // weight [3, dim]
        copyParamsContiguous.blockLen = this->curBaseDim * sizeof(DTYPE);
        copyParamsContiguous.srcStride = (this->tilingData_->dimSize - this->curBaseDim) * sizeof(DTYPE);
        copyParamsContiguous.dstStride = this->curBaseDim * sizeof(DTYPE) / BLOCK_SIZE;
        int64_t gmOffset = this->tilingData_->baseDim * this->baseDimIdx;
        DataCopyPad(localW0, this->weightGm[gmOffset], copyParamsContiguous, padParams);
        this->inQueueW.EnQue(weightFp32);
        weightFp32 = this->inQueueW.template DeQue<float>();
        localW0 = weightFp32.template ReinterpretCast<DTYPE>()[this->curBaseDim];
        localW1 = localW0[this->curBaseDim * NUM_TWO];
        localW2 = localW1[this->curBaseDim * NUM_TWO];
        LocalTensor<float> localW0FP32 = weightFp32;
        LocalTensor<float> localW1FP32 = weightFp32[this->curBaseDim];
        LocalTensor<float> localW2FP32 = weightFp32[this->curBaseDim * NUM_TWO];
        Cast(localW0FP32, localW0, RoundMode::CAST_NONE, this->curBaseDim);
        Cast(localW1FP32, localW1, RoundMode::CAST_NONE, this->curBaseDim);
        Cast(localW2FP32, localW2, RoundMode::CAST_NONE, this->curBaseDim);
        PipeBarrier<PIPE_V>();
        // Residual connection: w2 += 1.0
        if (this->tilingData_->residual) {
            Adds(localW2FP32, localW2FP32, float(1.0), this->curBaseDim);
            PipeBarrier<PIPE_V>();
        }
        w0Fp32 = weightFp32;
        w1Fp32 = weightFp32[this->curBaseDim];
        w2Fp32 = weightFp32[this->curBaseDim * NUM_TWO];
        // Get TBuf
        y0Fp32 = this->y0.template Get<float>();
        y1Fp32 = this->y1.template Get<float>();
        y2Fp32 = this->y2.template Get<float>();
        xFp32_ = this->xFp32.template Get<float>();

        for (int64_t loopId = 0; loopId < this->curBlockFactor; ++loopId) {
            // Check the two moments:
            // 1、seqId == 0, the first token of a new batch
            // 2、loopId == 0, the first token of cur core(the core may start in the middle of a batch)
            // the rest of token is non-padding batch
            if (this->seqId == NUM_ZERO || loopId == NUM_ZERO) {
                GetCacheLine(this->batchId, this->seqLen);
                if (readCacheLine == this->tilingData_->padSlotId) {
                    // tokens from seqId to the end of cur batch
                    int64_t batchRemaining = this->seqLen - this->seqId;
